        pub fn clip(self: Self, min_value: T, max_value: T) SparseError!Self {
            try validateSparseValueRange(T, min_value, max_value);
            const out = try self.clone();
            for (out.values) |*value| {
                if (value.* < min_value) {
                    value.* = min_value;
                } else if (value.* > max_value) {
                    value.* = max_value;
                }
            }
            return out;
        }

