        }

        pub fn clipMax(self: Self, max_value: T) SparseError!Self {
            ensureNumeric(T);
            const out = try self.clone();
            for (out.values) |*value| {
                if (value.* > max_value) value.* = max_value;
            }
            return out;
        }

        pub fn minimumScalar(self: Self, scalar: T) SparseError!Self {
