        pub fn toDense(self: Self) SparseError!array_mod.Array(T) {
            var out = try array_mod.Array(T).zeros(self.allocator, &.{ self.rows, self.cols });
            errdefer out.deinit();
            for (0..self.cols) |c| {
                for (self.col_offsets[c]..self.col_offsets[c + 1]) |pos| {
                    const index = self.row_indices[pos] * self.cols + c;
                    out.data[index] = addSparseValue(T, out.data[index], self.values[pos]);
                }
            }
            return out;
        }

        pub fn toDenseOut(self: Self, out: array_mod.Array(T)) SparseError!void {
            try sparseDenseCopyOut(T, try self.toDense(), out);
        }

        pub fn toArray(self: Self) SparseError!array_mod.Array(T) {
            return self.toDense();
        }

        pub fn toArrayOut(self: Self, out: array_mod.Array(T)) SparseError!void {
            try self.toDenseOut(out);
        }

        pub fn asSlice(self: Self) SparseError![]T {
            _ = self;
            return error.InvalidShape;
        }

        pub fn asConstSlice(self: Self) SparseError![]const T {
            _ = self;
            return error.InvalidShape;
        }

        pub fn copyToSlice(self: Self, out: []T) SparseError!void {
            var dense = try self.toDense();
            defer dense.deinit();
            try dense.copyToSlice(out);
        }

        pub fn toOwnedSlice(self: Self, allocator: std.mem.Allocator) SparseError![]T {
            var dense = try self.toDense();
            defer dense.deinit();
            return dense.toOwnedSlice(allocator);
        }

        pub fn toOwnedString(self: Self, allocator: std.mem.Allocator) SparseError![]u8 {
            var dense = try self.toDense();
            defer dense.deinit();
            return dense.toOwnedString(allocator);
