        pub fn emptyColumnCount(self: Self) usize {
            var empty_count: usize = 0;
            for (0..self.cols) |col| {
                if (self.col_offsets[col] == self.col_offsets[col + 1]) empty_count += 1;
            }
            return empty_count;
