test "sparse occupancy diagnostics" {
    const gpa = std.testing.allocator;
    var coo = try cooFromSlices(f64, gpa, 3, 4, &.{ 0, 0, 2 }, &.{ 0, 2, 0 }, &.{ 1.0, 2.0, 3.0 });
    defer coo.deinit();

    try std.testing.expectApproxEqAbs(@as(f64, 1), try coo.averageRowNnz(), 1e-12);
