            var count_scalar_out = try array_mod.Array(usize).zeros(matrix.allocator, &.{});
            defer count_scalar_out.deinit();
            try matrix.countNonzeroAxesOut(&.{ 0, 1 }, false, count_scalar_out);
            try std.testing.expectEqualSlices(usize, all_axes.data, count_scalar_out.data);

            var count_no_axes_out = try array_mod.Array(usize).zeros(matrix.allocator, &.{ 2, 3 });
            defer count_no_axes_out.deinit();
            try matrix.countNonzeroDimsOut(&.{}, false, count_no_axes_out);
            try std.testing.expectEqualSlices(usize, no_axes.data, count_no_axes_out.data);

            var flat = try matrix.flatNonzero();
            defer flat.deinit();
            try std.testing.expectEqualSlices(usize, &.{3}, flat.shape);
            try std.testing.expectEqualSlices(usize, &.{ 0, 4, 5 }, flat.data);
            var flat_out = try array_mod.Array(usize).zeros(matrix.allocator, &.{3});
            defer flat_out.deinit();
            try matrix.flatNonzeroOut(flat_out);
            try std.testing.expectEqualSlices(usize, flat.data, flat_out.data);

            var nonzero = try matrix.nonzero();
            defer nonzero.deinit();
            try std.testing.expectEqualSlices(usize, &.{ 3, 2 }, nonzero.shape);
            try std.testing.expectEqualSlices(usize, &.{ 0, 0, 1, 1, 1, 2 }, nonzero.data);
            var nonzero_out = try array_mod.Array(usize).zeros(matrix.allocator, &.{ 3, 2 });
            defer nonzero_out.deinit();
            try matrix.nonzeroOut(nonzero_out);
            try std.testing.expectEqualSlices(usize, nonzero.data, nonzero_out.data);

            var argwhere = try matrix.argwhere();
            defer argwhere.deinit();
            try std.testing.expectEqualSlices(usize, nonzero.shape, argwhere.shape);
            try std.testing.expectEqualSlices(usize, nonzero.data, argwhere.data);
            try matrix.argwhereOut(nonzero_out);
            try std.testing.expectEqualSlices(usize, argwhere.data, nonzero_out.data);

            var where_indices = try matrix.whereIndices();
            defer where_indices.deinit();
            try std.testing.expectEqualSlices(usize, nonzero.shape, where_indices.shape);
            try std.testing.expectEqualSlices(usize, nonzero.data, where_indices.data);
            try matrix.whereIndicesOut(nonzero_out);
            try std.testing.expectEqualSlices(usize, where_indices.data, nonzero_out.data);
        }
    }.check;
    const expectWhere = struct {
        fn expectArray(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            try std.testing.expectEqualSlices(f64, expected, values.data);
        }

        fn expectMatrix(values: array_mod.Array(f64), expected: []const f64) !void {
            try expectArray(values, &.{ 2, 3 }, expected);
        }

        fn check(comptime Matrix: type, matrix: Matrix, rhs_matrix: Matrix, rhs_dense: array_mod.Array(f64), mask: array_mod.Array(bool)) !void {
            var selected = try matrix.where(mask, rhs_matrix);
            defer selected.deinit();
            try expectMatrix(selected, &.{ 1, 0, 0, 0, 2, 6 });

            var selected_array = try matrix.whereArray(mask, rhs_dense);
            defer selected_array.deinit();
            try expectMatrix(selected_array, &.{ 1, 0, 0, 0, 2, 6 });

            var selected_scalar = try matrix.whereScalar(mask, -9);
            defer selected_scalar.deinit();
            try expectMatrix(selected_scalar, &.{ 1, -9, 0, -9, 2, -9 });

            var copied = try matrix.copyWhere(mask, rhs_matrix);
            defer copied.deinit();
            try expectMatrix(copied, &.{ 4, 0, 0, 0, -2, 3 });

            var copied_array = try matrix.copyWhereFromArray(mask, rhs_dense);
            defer copied_array.deinit();
            try expectMatrix(copied_array, &.{ 1, 0, 0, 0, 2, 6 });

            var where_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer where_out.deinit();
            try matrix.whereOut(mask, rhs_matrix, where_out);
            try expectMatrix(where_out, &.{ 1, 0, 0, 0, 2, 6 });
            try matrix.whereArrayOut(mask, rhs_dense, where_out);
            try expectMatrix(where_out, &.{ 1, 0, 0, 0, 2, 6 });
            try matrix.whereScalarOut(mask, -9, where_out);
            try expectMatrix(where_out, &.{ 1, -9, 0, -9, 2, -9 });
            try matrix.copyWhereOut(mask, rhs_matrix, where_out);
            try expectMatrix(where_out, &.{ 4, 0, 0, 0, -2, 3 });
            try matrix.copyWhereFromArrayOut(mask, rhs_dense, where_out);
            try expectMatrix(where_out, &.{ 1, 0, 0, 0, 2, 6 });

            var masked = try matrix.maskedSelect(mask);
            defer masked.deinit();
            try std.testing.expectEqualSlices(usize, &.{3}, masked.shape);
            try std.testing.expectEqualSlices(f64, &.{ 1, 0, 2 }, masked.data);
            var masked_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{3});
            defer masked_out.deinit();
            try matrix.maskedSelectOut(mask, masked_out);
            try std.testing.expectEqualSlices(f64, masked.data, masked_out.data);

            var filled = try matrix.maskedFill(mask, -7);
            defer filled.deinit();
            try expectMatrix(filled, &.{ -7, 0, -7, 0, -7, 3 });
            try matrix.maskedFillOut(mask, -7, where_out);
            try expectMatrix(where_out, filled.data);

            var put_scalar = try matrix.maskedPutScalar(mask, -8);
            defer put_scalar.deinit();
            try expectMatrix(put_scalar, &.{ -8, 0, -8, 0, -8, 3 });
            try matrix.maskedPutScalarOut(mask, -8, where_out);
            try expectMatrix(where_out, put_scalar.data);

            var put_mask_scalar = try matrix.putMaskScalar(mask, -6);
            defer put_mask_scalar.deinit();
