    const expectMatrixPredicates = struct {
        fn check(comptime Matrix: type, upper: Matrix, diagonal: Matrix) !void {
            try std.testing.expect(!(try upper.isDiagonalMatrix()));
            try std.testing.expect(try upper.isUpperTriangular());
            try std.testing.expect(!(try upper.isLowerTriangular()));
            try std.testing.expect(!(try upper.isSymmetric(1e-12, 1e-12)));

            try std.testing.expect(try diagonal.isDiagonalMatrix());
            try std.testing.expect(try diagonal.isUpperTriangular());
            try std.testing.expect(try diagonal.isLowerTriangular());
            try std.testing.expect(try diagonal.isSymmetric(1e-12, 1e-12));

            try std.testing.expectApproxEqAbs(@as(f64, 3), try upper.det(), 1e-12);
            var inverse = try upper.inverse();
            defer inverse.deinit();
            try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, inverse.shape);
            try std.testing.expectApproxEqAbs(@as(f64, 1), inverse.data[0], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, -2.0 / 3.0), inverse.data[1], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, 0), inverse.data[2], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, 1.0 / 3.0), inverse.data[3], 1e-12);
            var matrix_out = try array_mod.Array(f64).zeros(upper.allocator, &.{ 2, 2 });
            defer matrix_out.deinit();
            try upper.inverseOut(matrix_out);
            for (inverse.data, matrix_out.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }

            var inverse_alias = try upper.inv();
            defer inverse_alias.deinit();
            try std.testing.expectEqualSlices(f64, inverse.data, inverse_alias.data);
            try upper.invOut(matrix_out);
            for (inverse_alias.data, matrix_out.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }

            var squared = try upper.matrixPower(2);
            defer squared.deinit();
            try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, squared.shape);
            try std.testing.expectApproxEqAbs(@as(f64, 1), squared.data[0], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, 8), squared.data[1], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, 0), squared.data[2], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, 9), squared.data[3], 1e-12);
            try upper.matrixPowerOut(2, matrix_out);
            for (squared.data, matrix_out.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }

            var rhs = try array_mod.Array(f64).fromSlice(upper.allocator, &.{ 5, 6 }, &.{2});
            defer rhs.deinit();
            var solution = try upper.solve(rhs);
            defer solution.deinit();
            try std.testing.expectEqualSlices(usize, &.{2}, solution.shape);
            try std.testing.expectApproxEqAbs(@as(f64, 1), solution.data[0], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, 2), solution.data[1], 1e-12);
            var vector_out = try array_mod.Array(f64).zeros(upper.allocator, &.{2});
            defer vector_out.deinit();
            try upper.solveOut(rhs, vector_out);
            for (solution.data, vector_out.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }

            var solution_array = try upper.solveArray(rhs);
            defer solution_array.deinit();
            try std.testing.expectEqualSlices(usize, solution.shape, solution_array.shape);
            for (solution.data, solution_array.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }
            try upper.solveArrayOut(rhs, vector_out);
            for (solution_array.data, vector_out.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }

            var matvec_product = try upper.matvec(rhs);
            defer matvec_product.deinit();
            try std.testing.expectEqualSlices(usize, &.{2}, matvec_product.shape);
            try std.testing.expectApproxEqAbs(@as(f64, 17), matvec_product.data[0], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, 18), matvec_product.data[1], 1e-12);

            var matvec_array_product = try upper.matvecArray(rhs);
            defer matvec_array_product.deinit();
            try std.testing.expectEqualSlices(usize, matvec_product.shape, matvec_array_product.shape);
            for (matvec_product.data, matvec_array_product.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }

            var identity_rhs = try array_mod.Array(f64).fromSlice(upper.allocator, &.{ 1, 0, 0, 1 }, &.{ 2, 2 });
            defer identity_rhs.deinit();
            var matmul_identity = try upper.matmul(identity_rhs);
            defer matmul_identity.deinit();
            try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, matmul_identity.shape);
            try std.testing.expectApproxEqAbs(@as(f64, 1), matmul_identity.data[0], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, 2), matmul_identity.data[1], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, 0), matmul_identity.data[2], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, 3), matmul_identity.data[3], 1e-12);

            var matmul_identity_array = try upper.matmulArray(identity_rhs);
            defer matmul_identity_array.deinit();
            try std.testing.expectEqualSlices(usize, matmul_identity.shape, matmul_identity_array.shape);
            for (matmul_identity.data, matmul_identity_array.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }
            var matmul_array_out = try array_mod.Array(f64).zeros(upper.allocator, &.{ 2, 2 });
            defer matmul_array_out.deinit();
            try upper.matmulArrayOut(identity_rhs, matmul_array_out);
            for (matmul_identity_array.data, matmul_array_out.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }

            var addend_rhs = try array_mod.Array(f64).fromSlice(upper.allocator, &.{ 1, 1, 1, 1 }, &.{ 2, 2 });
            defer addend_rhs.deinit();
            var matmul_out = try array_mod.Array(f64).zeros(upper.allocator, &.{ 2, 2 });
            defer matmul_out.deinit();
            try upper.matmulOut(identity_rhs, matmul_out);
            try std.testing.expectEqualSlices(usize, matmul_identity.shape, matmul_out.shape);
            for (matmul_identity.data, matmul_out.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }

            var matmul_added = try upper.matmulAdd(identity_rhs, addend_rhs);
            defer matmul_added.deinit();
            try std.testing.expectEqualSlices(usize, matmul_identity.shape, matmul_added.shape);
            try std.testing.expectApproxEqAbs(@as(f64, 2), matmul_added.data[0], 1e-12);
            try std.testing.expectApproxEqAbs(@as(f64, 4), matmul_added.data[3], 1e-12);

            var matmul_added_out = try array_mod.Array(f64).zeros(upper.allocator, &.{ 2, 2 });
            defer matmul_added_out.deinit();
            try upper.matmulAddOut(identity_rhs, addend_rhs, matmul_added_out);
            try std.testing.expectEqualSlices(usize, matmul_added.shape, matmul_added_out.shape);
            for (matmul_added.data, matmul_added_out.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }

            var matmul_added_array = try upper.matmulAddArray(identity_rhs, addend_rhs);
            defer matmul_added_array.deinit();
            try std.testing.expectEqualSlices(usize, matmul_added.shape, matmul_added_array.shape);
            for (matmul_added.data, matmul_added_array.data) |expected, actual| {
                try std.testing.expectApproxEqAbs(expected, actual, 1e-12);
            }
