test "sparse dense count and histogram helpers" {
    const gpa = std.testing.allocator;

    const expectCounts = struct {
        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var counts = try matrix.bincount(5);
            defer counts.deinit();
            try std.testing.expectEqualSlices(usize, &.{5}, counts.shape);
            try std.testing.expectEqualSlices(usize, &.{ 3, 1, 1, 1, 0 }, counts.data);
            var counts_out = try array_mod.Array(usize).zeros(matrix.allocator, &.{5});
            defer counts_out.deinit();
            try matrix.bincountOut(5, counts_out);
            try std.testing.expectEqualSlices(usize, counts.data, counts_out.data);

            var weights = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{
                1, 2, 3,
                4, 5, 6,
            }, &.{ 2, 3 });
            defer weights.deinit();
            var weighted_counts = try matrix.bincountWeighted(f64, weights, 5);
            defer weighted_counts.deinit();
            try std.testing.expectEqualSlices(usize, &.{5}, weighted_counts.shape);
            try std.testing.expectEqualSlices(f64, &.{ 8, 3, 4, 6, 0 }, weighted_counts.data);
            var weighted_counts_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{5});
            defer weighted_counts_out.deinit();
            try matrix.bincountWeightedOut(f64, weights, 5, weighted_counts_out);
            try std.testing.expectEqualSlices(f64, weighted_counts.data, weighted_counts_out.data);

            var bad_weights = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{ 1, 2, 3, 4, 5 }, &.{5});
            defer bad_weights.deinit();
            try std.testing.expectError(error.ShapeMismatch, matrix.bincountWeighted(f64, bad_weights, 5));
        }
    }.check;

    var codes = try cooFromSlices(u32, gpa, 2, 3, &.{ 0, 1, 1 }, &.{ 2, 0, 2 }, &.{ 1, 2, 3 });
    defer codes.deinit();
    try expectCounts(@TypeOf(codes), codes);
    var codes_csr = try codes.toCsr();
    defer codes_csr.deinit();
    try expectCounts(@TypeOf(codes_csr), codes_csr);
    var codes_csc = try codes.toCsc();
    defer codes_csc.deinit();
    try expectCounts(@TypeOf(codes_csc), codes_csc);

    var negative_codes = try cooFromSlices(i32, gpa, 1, 2, &.{0}, &.{1}, &.{-1});
    defer negative_codes.deinit();
    try std.testing.expectError(error.InvalidShape, negative_codes.bincount(0));

    const expectHistogram = struct {
        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var hist = try matrix.histogram(5, .{ .min = 0, .max = 5 });
            defer hist.counts.deinit();
            defer hist.edges.deinit();
            try std.testing.expectEqualSlices(usize, &.{5}, hist.counts.shape);
            try std.testing.expectEqualSlices(usize, &.{ 3, 1, 1, 0, 1 }, hist.counts.data);
            try std.testing.expectEqualSlices(usize, &.{6}, hist.edges.shape);
            try std.testing.expectEqualSlices(f64, &.{ 0, 1, 2, 3, 4, 5 }, hist.edges.data);
            var counts_out = try array_mod.Array(usize).zeros(matrix.allocator, &.{5});
            defer counts_out.deinit();
            var edges_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{6});
            defer edges_out.deinit();
            try matrix.histogramOut(5, .{ .min = 0, .max = 5 }, counts_out, edges_out);
            try std.testing.expectEqualSlices(usize, hist.counts.data, counts_out.data);
            try std.testing.expectEqualSlices(f64, hist.edges.data, edges_out.data);

            try std.testing.expectError(error.InvalidShape, matrix.histogram(0, .{ .min = 0, .max = 5 }));
        }
    }.check;

    var samples = try cooFromSlices(f64, gpa, 2, 3, &.{ 0, 0, 1 }, &.{ 1, 2, 2 }, &.{ 1, 2, 5 });
    defer samples.deinit();
    try expectHistogram(@TypeOf(samples), samples);
    var samples_csr = try samples.toCsr();
    defer samples_csr.deinit();
    try expectHistogram(@TypeOf(samples_csr), samples_csr);
    var samples_csc = try samples.toCsc();
    defer samples_csc.deinit();
    try expectHistogram(@TypeOf(samples_csc), samples_csc);
}

test "sparse dense nanarg reduction helpers" {
    const gpa = std.testing.allocator;

    const expectNanArgReductions = struct {
        fn expectUsizeArray(values: array_mod.Array(usize), shape: []const usize, expected: []const usize) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            try std.testing.expectEqualSlices(usize, expected, values.data);
        }

        fn check(comptime Matrix: type, matrix: Matrix) !void {
            try std.testing.expectEqual(@as(usize, 2), try matrix.nanargmax());
            try std.testing.expectEqual(@as(usize, 4), try matrix.nanargmin());

            var flat_argmax = try matrix.nanargmaxAxis(null, false);
            defer flat_argmax.deinit();
            try expectUsizeArray(flat_argmax, &.{}, &.{2});
            var flat_arg_out = try array_mod.Array(usize).zeros(matrix.allocator, &.{});
            defer flat_arg_out.deinit();
            try matrix.nanargmaxAxisOut(null, false, flat_arg_out);
            try std.testing.expectEqualSlices(usize, flat_argmax.data, flat_arg_out.data);
            var flat_argmin_keepdim = try matrix.nanargminAxis(null, true);
            defer flat_argmin_keepdim.deinit();
            try expectUsizeArray(flat_argmin_keepdim, &.{ 1, 1 }, &.{4});
            var flat_arg_keepdim_out = try array_mod.Array(usize).zeros(matrix.allocator, &.{ 1, 1 });
            defer flat_arg_keepdim_out.deinit();
            try matrix.nanargminAxisOut(null, true, flat_arg_keepdim_out);
            try std.testing.expectEqualSlices(usize, flat_argmin_keepdim.data, flat_arg_keepdim_out.data);

            var row_argmax = try matrix.nanargmaxAxis(1, false);
            defer row_argmax.deinit();
            try expectUsizeArray(row_argmax, &.{2}, &.{ 2, 0 });
            var row_arg_out = try array_mod.Array(usize).zeros(matrix.allocator, &.{2});
            defer row_arg_out.deinit();
            try matrix.nanargmaxAxisOut(1, false, row_arg_out);
            try std.testing.expectEqualSlices(usize, row_argmax.data, row_arg_out.data);
            var row_argmax_dim = try matrix.nanargmaxDim(-1, true);
            defer row_argmax_dim.deinit();
            try expectUsizeArray(row_argmax_dim, &.{ 2, 1 }, row_argmax.data);
            var row_arg_keepdim_out = try array_mod.Array(usize).zeros(matrix.allocator, &.{ 2, 1 });
            defer row_arg_keepdim_out.deinit();
            try matrix.nanargmaxDimOut(-1, true, row_arg_keepdim_out);
            try std.testing.expectEqualSlices(usize, row_argmax_dim.data, row_arg_keepdim_out.data);

            var row_argmin = try matrix.nanargminAxis(1, false);
            defer row_argmin.deinit();
            try expectUsizeArray(row_argmin, &.{2}, &.{ 1, 1 });
            try matrix.nanargminAxisOut(1, false, row_arg_out);
            try std.testing.expectEqualSlices(usize, row_argmin.data, row_arg_out.data);
            var row_argmin_dim = try matrix.nanargminDim(-1, true);
            defer row_argmin_dim.deinit();
            try expectUsizeArray(row_argmin_dim, &.{ 2, 1 }, row_argmin.data);
            try matrix.nanargminDimOut(-1, true, row_arg_keepdim_out);
            try std.testing.expectEqualSlices(usize, row_argmin_dim.data, row_arg_keepdim_out.data);

            var column_argmax = try matrix.nanargmaxAxis(0, false);
            defer column_argmax.deinit();
            try expectUsizeArray(column_argmax, &.{3}, &.{ 1, 0, 0 });
            var column_arg_out = try array_mod.Array(usize).zeros(matrix.allocator, &.{3});
            defer column_arg_out.deinit();
            try matrix.nanargmaxAxisOut(0, false, column_arg_out);
            try std.testing.expectEqualSlices(usize, column_argmax.data, column_arg_out.data);
            var column_argmin = try matrix.nanargminDim(0, false);
            defer column_argmin.deinit();
            try expectUsizeArray(column_argmin, &.{3}, &.{ 1, 1, 0 });
            try matrix.nanargminDimOut(0, false, column_arg_out);
            try std.testing.expectEqualSlices(usize, column_argmin.data, column_arg_out.data);
        }
    }.check;

    var matrix = try cooFromSlices(f64, gpa, 2, 3, &.{ 0, 0, 1, 1 }, &.{ 0, 2, 1, 2 }, &.{ std.math.nan(f64), 2, -1, std.math.nan(f64) });
    defer matrix.deinit();
    try expectNanArgReductions(@TypeOf(matrix), matrix);
    var matrix_csr = try matrix.toCsr();
    defer matrix_csr.deinit();
    try expectNanArgReductions(@TypeOf(matrix_csr), matrix_csr);
    var matrix_csc = try matrix.toCsc();
    defer matrix_csc.deinit();
    try expectNanArgReductions(@TypeOf(matrix_csc), matrix_csc);

    var all_nan = try cooFromSlices(f64, gpa, 1, 2, &.{ 0, 0 }, &.{ 0, 1 }, &.{ std.math.nan(f64), std.math.nan(f64) });
    defer all_nan.deinit();
    try std.testing.expectError(error.EmptyArray, all_nan.nanargmax());
    try std.testing.expectError(error.EmptyArray, all_nan.nanargminAxis(1, false));
}

test "sparse dense quantile helpers" {
    const gpa = std.testing.allocator;

    const expectQuantiles = struct {
        fn expectArray(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            for (expected, values.data) |want, got| {
                if (std.math.isInf(want) or std.math.isInf(got)) {
                    try std.testing.expectEqual(want, got);
                } else if (std.math.isNan(want) or std.math.isNan(got)) {
                    try std.testing.expect(std.math.isNan(want) and std.math.isNan(got));
                } else {
                    try std.testing.expectApproxEqAbs(want, got, 1e-12);
                }
            }
        }

        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var flat_median = try matrix.median(null, false);
            defer flat_median.deinit();
            try expectArray(flat_median, &.{}, &.{0.5});
            var scalar_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{});
            defer scalar_out.deinit();
            var all_axes_keepdim_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 1, 1 });
            defer all_axes_keepdim_out.deinit();
            try matrix.medianOut(null, false, scalar_out);
            try expectArray(scalar_out, &.{}, flat_median.data);

            var flat_upper_quartile = try matrix.quantile(0.75, null, true);
            defer flat_upper_quartile.deinit();
            try expectArray(flat_upper_quartile, &.{ 1, 1 }, &.{1.75});
            try matrix.quantileOut(0.75, null, true, all_axes_keepdim_out);
            try expectArray(all_axes_keepdim_out, &.{ 1, 1 }, flat_upper_quartile.data);

            var row_medians = try matrix.median(1, false);
            defer row_medians.deinit();
            try expectArray(row_medians, &.{2}, &.{ 0, 2 });
            var row_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{2});
            defer row_out.deinit();
            try matrix.medianOut(1, false, row_out);
            try expectArray(row_out, &.{2}, row_medians.data);

            var row_median_dims = try matrix.medianDim(-1, true);
            defer row_median_dims.deinit();
            try expectArray(row_median_dims, &.{ 2, 1 }, row_medians.data);
            var row_keepdim_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 1 });
            defer row_keepdim_out.deinit();
            try matrix.medianDimOut(-1, true, row_keepdim_out);
            try expectArray(row_keepdim_out, &.{ 2, 1 }, row_median_dims.data);

            var column_medians = try matrix.median(0, false);
            defer column_medians.deinit();
            try expectArray(column_medians, &.{3}, &.{ 0.5, 1, 1.5 });
            var column_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{3});
            defer column_out.deinit();
            try matrix.medianOut(0, false, column_out);
            try expectArray(column_out, &.{3}, column_medians.data);

            var all_axes_median = try matrix.medianAxes(&.{ 0, 1 }, false);
            defer all_axes_median.deinit();
            try expectArray(all_axes_median, &.{}, flat_median.data);
            try matrix.medianAxesOut(&.{ 0, 1 }, false, scalar_out);
            try expectArray(scalar_out, &.{}, all_axes_median.data);

            var all_axes_median_keepdim = try matrix.medianDims(&.{ 0, 1 }, true);
            defer all_axes_median_keepdim.deinit();
            try expectArray(all_axes_median_keepdim, &.{ 1, 1 }, flat_median.data);
            try matrix.medianDimsOut(&.{ 0, 1 }, true, all_axes_keepdim_out);
            try expectArray(all_axes_keepdim_out, &.{ 1, 1 }, all_axes_median_keepdim.data);

            var lower_quartile = try matrix.quantile(0.25, null, false);
            defer lower_quartile.deinit();
            try expectArray(lower_quartile, &.{}, &.{0});

            var row_upper_quartile = try matrix.quantileDim(0.75, -1, false);
            defer row_upper_quartile.deinit();
            try expectArray(row_upper_quartile, &.{2}, &.{ 0.5, 2.5 });
            try matrix.quantileDimOut(0.75, -1, false, row_out);
            try expectArray(row_out, &.{2}, row_upper_quartile.data);

            var all_axes_quantile = try matrix.quantileAxes(0.5, &.{ 0, 1 }, true);
            defer all_axes_quantile.deinit();
            try expectArray(all_axes_quantile, &.{ 1, 1 }, flat_median.data);
            try matrix.quantileAxesOut(0.5, &.{ 0, 1 }, true, all_axes_keepdim_out);
            try expectArray(all_axes_keepdim_out, &.{ 1, 1 }, all_axes_quantile.data);

            var all_axes_quantile_dims = try matrix.quantileDims(0.25, &.{ 0, 1 }, false);
            defer all_axes_quantile_dims.deinit();
            try expectArray(all_axes_quantile_dims, &.{}, lower_quartile.data);
            try matrix.quantileDimsOut(0.25, &.{ 0, 1 }, false, scalar_out);
            try expectArray(scalar_out, &.{}, all_axes_quantile_dims.data);

            var upper_percentile = try matrix.percentile(75, null, false);
            defer upper_percentile.deinit();
            try expectArray(upper_percentile, &.{}, &.{1.75});
            try matrix.percentileOut(75, null, false, scalar_out);
            try expectArray(scalar_out, &.{}, upper_percentile.data);

            var column_percentile = try matrix.percentileDim(50, 0, false);
            defer column_percentile.deinit();
            try expectArray(column_percentile, &.{3}, column_medians.data);
            try matrix.percentileDimOut(50, 0, false, column_out);
            try expectArray(column_out, &.{3}, column_percentile.data);

            var all_axes_percentile = try matrix.percentileAxes(50, &.{ 0, 1 }, true);
            defer all_axes_percentile.deinit();
            try expectArray(all_axes_percentile, &.{ 1, 1 }, flat_median.data);
            try matrix.percentileAxesOut(50, &.{ 0, 1 }, true, all_axes_keepdim_out);
            try expectArray(all_axes_keepdim_out, &.{ 1, 1 }, all_axes_percentile.data);

            var all_axes_percentile_dims = try matrix.percentileDims(25, &.{ 0, 1 }, false);
            defer all_axes_percentile_dims.deinit();
            try expectArray(all_axes_percentile_dims, &.{}, lower_quartile.data);
            try matrix.percentileDimsOut(25, &.{ 0, 1 }, false, scalar_out);
            try expectArray(scalar_out, &.{}, all_axes_percentile_dims.data);

            try std.testing.expectError(error.InvalidShape, matrix.quantile(-0.1, null, false));
            try std.testing.expectError(error.InvalidShape, matrix.percentile(101, null, false));
            try std.testing.expectError(error.InvalidAxis, matrix.median(2, false));
        }
    }.check;

    var matrix = try cooFromSlices(f64, gpa, 2, 3, &.{ 0, 1, 1 }, &.{ 0, 1, 2 }, &.{ 1, 2, 3 });
    defer matrix.deinit();
    try expectQuantiles(@TypeOf(matrix), matrix);
    var matrix_csr = try matrix.toCsr();
    defer matrix_csr.deinit();
    try expectQuantiles(@TypeOf(matrix_csr), matrix_csr);
    var matrix_csc = try matrix.toCsc();
    defer matrix_csc.deinit();
    try expectQuantiles(@TypeOf(matrix_csc), matrix_csc);
}

test "sparse dense fused elementwise helpers" {
    const gpa = std.testing.allocator;

    const expectFused = struct {
        fn expectArray(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            for (expected, values.data) |want, got| {
                if (std.math.isInf(want) or std.math.isInf(got)) {
                    try std.testing.expectEqual(want, got);
                } else if (std.math.isNan(want) or std.math.isNan(got)) {
                    try std.testing.expect(std.math.isNan(want) and std.math.isNan(got));
                } else {
                    try std.testing.expectApproxEqAbs(want, got, 1e-12);
                }
            }
        }

        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var end_values = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{
                3, 4, 5,
                6, 7, 8,
            }, &.{ 2, 3 });
            defer end_values.deinit();
            var weights = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{
                0,   0.25, 0.5,
                0.5, 0.75, 1,
            }, &.{ 2, 3 });
            defer weights.deinit();

            var lerped = try matrix.lerp(end_values, weights);
            defer lerped.deinit();
            try expectArray(lerped, &.{ 2, 3 }, &.{ 1, 1, 2.5, 3, 5.75, 8 });
            var fused_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer fused_out.deinit();
            try matrix.lerpOut(end_values, weights, fused_out);
            try expectArray(fused_out, &.{ 2, 3 }, lerped.data);

            var lerp_alias = try matrix.lerpArray(end_values, weights);
            defer lerp_alias.deinit();
            try expectArray(lerp_alias, &.{ 2, 3 }, lerped.data);
            try matrix.lerpArrayOut(end_values, weights, fused_out);
            try expectArray(fused_out, &.{ 2, 3 }, lerp_alias.data);

            var lerped_scalar = try matrix.lerpScalar(end_values, 0.5);
            defer lerped_scalar.deinit();
            try expectArray(lerped_scalar, &.{ 2, 3 }, &.{ 2, 2, 2.5, 3, 4.5, 5.5 });
            try matrix.lerpScalarOut(end_values, 0.5, fused_out);
            try expectArray(fused_out, &.{ 2, 3 }, lerped_scalar.data);

            var added_array = try matrix.addArray(end_values);
            defer added_array.deinit();
            try expectArray(added_array, &.{ 2, 3 }, &.{ 4, 4, 5, 6, 9, 11 });
            try matrix.addArrayOut(end_values, fused_out);
            try expectArray(fused_out, &.{ 2, 3 }, added_array.data);

            var subtracted_array = try matrix.subArray(end_values);
            defer subtracted_array.deinit();
            try expectArray(subtracted_array, &.{ 2, 3 }, &.{ -2, -4, -5, -6, -5, -5 });
            try matrix.subArrayOut(end_values, fused_out);
            try expectArray(fused_out, &.{ 2, 3 }, subtracted_array.data);

            var multiplied_array = try matrix.mulArray(end_values);
            defer multiplied_array.deinit();
            try expectArray(multiplied_array, &.{ 2, 3 }, &.{ 3, 0, 0, 0, 14, 24 });
            try matrix.mulArrayOut(end_values, fused_out);
            try expectArray(fused_out, &.{ 2, 3 }, multiplied_array.data);

            var divided_array = try matrix.divArray(end_values);
            defer divided_array.deinit();
            try expectArray(divided_array, &.{ 2, 3 }, &.{ 1.0 / 3.0, 0, 0, 0, 2.0 / 7.0, 3.0 / 8.0 });
            try matrix.divArrayOut(end_values, fused_out);
            try expectArray(fused_out, &.{ 2, 3 }, divided_array.data);

            var added_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer added_out.deinit();
            try matrix.addOut(end_values, added_out);
            try expectArray(added_out, &.{ 2, 3 }, added_array.data);

            var subtracted_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer subtracted_out.deinit();
            try matrix.subOut(end_values, subtracted_out);
            try expectArray(subtracted_out, &.{ 2, 3 }, subtracted_array.data);

            var multiplied_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer multiplied_out.deinit();
            try matrix.mulOut(end_values, multiplied_out);
            try expectArray(multiplied_out, &.{ 2, 3 }, multiplied_array.data);

            var divided_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer divided_out.deinit();
            try matrix.divOut(end_values, divided_out);
            try expectArray(divided_out, &.{ 2, 3 }, divided_array.data);

            var scalar_added_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer scalar_added_out.deinit();
            try matrix.addScalarOut(2, scalar_added_out);
            try expectArray(scalar_added_out, &.{ 2, 3 }, &.{ 3, 2, 2, 2, 4, 5 });

            var scalar_multiplied_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer scalar_multiplied_out.deinit();
            try matrix.mulScalarOut(2, scalar_multiplied_out);
            try expectArray(scalar_multiplied_out, &.{ 2, 3 }, &.{ 2, 0, 0, 0, 4, 6 });

            var hypot_array = try matrix.hypotArray(end_values);
            defer hypot_array.deinit();
            try expectArray(hypot_array, &.{ 2, 3 }, &.{
                std.math.hypot(@as(f64, 1), @as(f64, 3)),
                4,
                5,
                6,
                std.math.hypot(@as(f64, 2), @as(f64, 7)),
                std.math.hypot(@as(f64, 3), @as(f64, 8)),
            });
            try matrix.hypotArrayOut(end_values, divided_out);
            try expectArray(divided_out, &.{ 2, 3 }, hypot_array.data);

            var atan2_array = try matrix.atan2Array(end_values);
            defer atan2_array.deinit();
            try expectArray(atan2_array, &.{ 2, 3 }, &.{
                std.math.atan2(@as(f64, 1), @as(f64, 3)),
                0,
                0,
                0,
                std.math.atan2(@as(f64, 2), @as(f64, 7)),
                std.math.atan2(@as(f64, 3), @as(f64, 8)),
            });
            try matrix.atan2ArrayOut(end_values, divided_out);
            try expectArray(divided_out, &.{ 2, 3 }, atan2_array.data);

            var arctan2_array = try matrix.arctan2Array(end_values);
            defer arctan2_array.deinit();
            try expectArray(arctan2_array, &.{ 2, 3 }, atan2_array.data);
            try matrix.arctan2ArrayOut(end_values, divided_out);
            try expectArray(divided_out, &.{ 2, 3 }, arctan2_array.data);

            var next_after_targets = try array_mod.Array(f64).full(matrix.allocator, &.{ 2, 3 }, 10);
            defer next_after_targets.deinit();
            var next_after_array = try matrix.nextAfterArray(next_after_targets);
            defer next_after_array.deinit();
            try expectArray(next_after_array, &.{ 2, 3 }, &.{
                std.math.nextAfter(f64, 1, 10),
                std.math.nextAfter(f64, 0, 10),
                std.math.nextAfter(f64, 0, 10),
                std.math.nextAfter(f64, 0, 10),
                std.math.nextAfter(f64, 2, 10),
                std.math.nextAfter(f64, 3, 10),
            });
            try matrix.nextAfterArrayOut(next_after_targets, divided_out);
            try expectArray(divided_out, &.{ 2, 3 }, next_after_array.data);

            var nextafter_array = try matrix.nextafterArray(next_after_targets);
            defer nextafter_array.deinit();
            try expectArray(nextafter_array, &.{ 2, 3 }, next_after_array.data);
            try matrix.nextafterArrayOut(next_after_targets, divided_out);
            try expectArray(divided_out, &.{ 2, 3 }, nextafter_array.data);

            var sign_values = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{
                -1, 1,  -1,
                1,  -1, 1,
            }, &.{ 2, 3 });
            defer sign_values.deinit();
            var copied_sign_array = try matrix.copysignArray(sign_values);
            defer copied_sign_array.deinit();
