            defer ldexp_broadcast.deinit();
            try expectArray(ldexp_broadcast, &.{ 2, 3 }, &.{ 1, 0, 0, 0, 4, 12 });

            var bad_exponents = try array_mod.Array(i32).zeros(matrix.allocator, &.{ 2, 2 });
