            try std.testing.expectError(error.ShapeMismatch, matrix.xlogy(bad_same_format));
            try std.testing.expectError(error.ShapeMismatch, matrix.clipArray(lower, bad));
        }
    }.check;

    var matrix = try cooFromSlices(f64, gpa, 2, 3, &.{ 0, 1, 1 }, &.{ 0, 1, 2 }, &.{ 1, 2, 3 });
    defer matrix.deinit();
    try expectFused(@TypeOf(matrix), matrix);
    var matrix_csr = try matrix.toCsr();
    defer matrix_csr.deinit();
    try expectFused(@TypeOf(matrix_csr), matrix_csr);
    var matrix_csc = try matrix.toCsc();
    defer matrix_csc.deinit();
    try expectFused(@TypeOf(matrix_csc), matrix_csc);
}

test "sparse dense signal helpers" {
    const gpa = std.testing.allocator;

    const expectSignal = struct {
        fn expectArray(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            for (expected, values.data) |want, got| try std.testing.expectApproxEqAbs(want, got, 1e-12);
        }

        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var kernel_coo = try cooFromSlices(
                f64,
                matrix.allocator,
                2,
                2,
                &.{ 0, 0, 1, 1 },
                &.{ 0, 1, 0, 1 },
                &.{ 1, 2, 3, 4 },
            );
            defer kernel_coo.deinit();
            var kernel_same_format = if (comptime Matrix == CooMatrix(f64))
                try kernel_coo.clone()
            else if (comptime Matrix == CsrMatrix(f64))
                try kernel_coo.toCsr()
            else if (comptime Matrix == CscMatrix(f64))
                try kernel_coo.toCsc()
            else
                @compileError("unexpected sparse matrix format");
            defer kernel_same_format.deinit();
            var kernel_dense = try kernel_coo.toDense();
            defer kernel_dense.deinit();

            var signal_sparse = try cooFromSlices(
                f64,
                matrix.allocator,
                1,
                4,
                &.{ 0, 0, 0, 0 },
                &.{ 0, 1, 2, 3 },
                &.{ 1, 2, 3, 4 },
            );
            defer signal_sparse.deinit();
            var signal_same_format = if (comptime Matrix == CooMatrix(f64))
                try signal_sparse.clone()
            else if (comptime Matrix == CsrMatrix(f64))
                try signal_sparse.toCsr()
            else if (comptime Matrix == CscMatrix(f64))
                try signal_sparse.toCsc()
            else
                @compileError("unexpected sparse matrix format");
            defer signal_same_format.deinit();
            var kernel_1d = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{ 1, 2 }, &.{2});
            defer kernel_1d.deinit();

            var convolved_1d = try signal_same_format.convolve1d(kernel_1d, .full);
            defer convolved_1d.deinit();
            try expectArray(convolved_1d, &.{5}, &.{ 1, 4, 7, 10, 8 });
            var signal_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{5});
            defer signal_out.deinit();
            try signal_same_format.convolve1dOut(kernel_1d, .full, signal_out);
            try expectArray(signal_out, &.{5}, convolved_1d.data);

            var convolved_1d_array = try signal_same_format.convolve1dArray(kernel_1d, .full);
            defer convolved_1d_array.deinit();
            try expectArray(convolved_1d_array, &.{5}, convolved_1d.data);
            try signal_same_format.convolve1dArrayOut(kernel_1d, .full, signal_out);
            try expectArray(signal_out, &.{5}, convolved_1d_array.data);

            var correlated_1d = try signal_same_format.correlate1d(kernel_1d, .full);
            defer correlated_1d.deinit();
            try expectArray(correlated_1d, &.{5}, &.{ 2, 5, 8, 11, 4 });
            try signal_same_format.correlate1dOut(kernel_1d, .full, signal_out);
            try expectArray(signal_out, &.{5}, correlated_1d.data);

            var correlated_1d_array = try signal_same_format.correlate1dArray(kernel_1d, .full);
            defer correlated_1d_array.deinit();
            try expectArray(correlated_1d_array, &.{5}, correlated_1d.data);
            try signal_same_format.correlate1dArrayOut(kernel_1d, .full, signal_out);
            try expectArray(signal_out, &.{5}, correlated_1d_array.data);

            var convolved = try matrix.convolve2d(kernel_same_format, .full);
            defer convolved.deinit();
            try expectArray(convolved, &.{ 3, 3 }, &.{ 1, 2, 0, 3, 6, 4, 0, 6, 8 });
            var matrix_full_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 3, 3 });
            defer matrix_full_out.deinit();
            try matrix.convolve2dOut(kernel_same_format, .full, matrix_full_out);
            try expectArray(matrix_full_out, &.{ 3, 3 }, convolved.data);

            var convolved_array = try matrix.convolve2dArray(kernel_dense, .full);
            defer convolved_array.deinit();
            try expectArray(convolved_array, &.{ 3, 3 }, convolved.data);
            try matrix.convolve2dArrayOut(kernel_dense, .full, matrix_full_out);
            try expectArray(matrix_full_out, &.{ 3, 3 }, convolved_array.data);

            var correlated = try matrix.correlate2d(kernel_same_format, .full);
            defer correlated.deinit();
            try expectArray(correlated, &.{ 3, 3 }, &.{ 4, 3, 0, 2, 9, 6, 0, 4, 2 });
            try matrix.correlate2dOut(kernel_same_format, .full, matrix_full_out);
            try expectArray(matrix_full_out, &.{ 3, 3 }, correlated.data);

            var correlated_array = try matrix.correlate2dArray(kernel_dense, .full);
            defer correlated_array.deinit();
            try expectArray(correlated_array, &.{ 3, 3 }, correlated.data);
            try matrix.correlate2dArrayOut(kernel_dense, .full, matrix_full_out);
            try expectArray(matrix_full_out, &.{ 3, 3 }, correlated_array.data);

            var same_convolution = try matrix.convolve2d(kernel_same_format, .same);
            defer same_convolution.deinit();
            try expectArray(same_convolution, &.{ 2, 2 }, &.{ 1, 2, 3, 6 });
            var matrix_same_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 2 });
            defer matrix_same_out.deinit();
            try matrix.convolve2dOut(kernel_same_format, .same, matrix_same_out);
            try expectArray(matrix_same_out, &.{ 2, 2 }, same_convolution.data);

            var bad_kernel = try array_mod.Array(f64).ones(matrix.allocator, &.{2});
            defer bad_kernel.deinit();
            try std.testing.expectError(error.NonMatrixArray, matrix.convolve2dArray(bad_kernel, .full));
            try std.testing.expectError(error.NonMatrixArray, matrix.correlate2dArray(bad_kernel, .full));
            try std.testing.expectError(error.NonVectorArray, matrix.convolve1d(bad_kernel, .full));
            try std.testing.expectError(error.NonVectorArray, matrix.correlate1d(bad_kernel, .full));
        }
    }.check;

    var matrix = try cooFromSlices(f64, gpa, 2, 2, &.{ 0, 1 }, &.{ 0, 1 }, &.{ 1, 2 });
    defer matrix.deinit();
    try expectSignal(@TypeOf(matrix), matrix);
    var matrix_csr = try matrix.toCsr();
    defer matrix_csr.deinit();
    try expectSignal(@TypeOf(matrix_csr), matrix_csr);
    var matrix_csc = try matrix.toCsc();
    defer matrix_csc.deinit();
    try expectSignal(@TypeOf(matrix_csc), matrix_csc);
}

test "sparse dense numeric array helpers" {
    const gpa = std.testing.allocator;

    const expectNumericArrays = struct {
        fn expectArray(values: array_mod.Array(i32), shape: []const usize, expected: []const i32) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            try std.testing.expectEqualSlices(i32, expected, values.data);
        }

        fn expectFloatArray(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            for (expected, values.data) |want, got| {
                if (std.math.isInf(want) or std.math.isInf(got)) {
                    try std.testing.expectEqual(want, got);
                } else {
                    try std.testing.expectApproxEqAbs(want, got, 1e-12);
                }
            }
        }

        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var exponents = try array_mod.Array(i32).fromSlice(matrix.allocator, &.{
                2, 2, 2,
                2, 2, 3,
            }, &.{ 2, 3 });
            defer exponents.deinit();
            var powers = try matrix.powArray(exponents);
            defer powers.deinit();
            try expectArray(powers, &.{ 2, 3 }, &.{ 4, 0, 0, 0, 1, 8 });
            var dense_binary_out = try array_mod.Array(i32).zeros(matrix.allocator, &.{ 2, 3 });
            defer dense_binary_out.deinit();
            try matrix.powArrayOut(exponents, dense_binary_out);
            try expectArray(dense_binary_out, &.{ 2, 3 }, powers.data);

            var divisors = try array_mod.Array(i32).fromSlice(matrix.allocator, &.{
                2, 2, 3,
                4, 5, 2,
            }, &.{ 2, 3 });
            defer divisors.deinit();
            var floored = try matrix.floorDivArray(divisors);
            defer floored.deinit();
            try expectArray(floored, &.{ 2, 3 }, &.{ 1, 0, 0, 0, -1, 1 });
            try matrix.floorDivArrayOut(divisors, dense_binary_out);
            try expectArray(dense_binary_out, &.{ 2, 3 }, floored.data);

            var modded = try matrix.modArray(divisors);
            defer modded.deinit();
            try expectArray(modded, &.{ 2, 3 }, &.{ 0, 0, 0, 0, 4, 0 });
            try matrix.modArrayOut(divisors, dense_binary_out);
            try expectArray(dense_binary_out, &.{ 2, 3 }, modded.data);

            var remainder_alias = try matrix.remainderArray(divisors);
            defer remainder_alias.deinit();
            try expectArray(remainder_alias, &.{ 2, 3 }, modded.data);
            try matrix.remainderArrayOut(divisors, dense_binary_out);
            try expectArray(dense_binary_out, &.{ 2, 3 }, remainder_alias.data);

            var promoted_rhs = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{
                0.5, 1, 2,
                3,   4, 5,
            }, &.{ 2, 3 });
            defer promoted_rhs.deinit();

            var promoted_sum = try matrix.addPromote(f64, promoted_rhs);
            defer promoted_sum.deinit();
            try expectFloatArray(promoted_sum, &.{ 2, 3 }, &.{ 2.5, 1, 2, 3, 3, 7 });
            var promoted_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer promoted_out.deinit();
            try matrix.addPromoteOut(f64, promoted_rhs, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_sum.data);

            var promoted_diff = try matrix.subPromote(f64, promoted_rhs);
            defer promoted_diff.deinit();
            try expectFloatArray(promoted_diff, &.{ 2, 3 }, &.{ 1.5, -1, -2, -3, -5, -3 });
            try matrix.subPromoteOut(f64, promoted_rhs, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_diff.data);

            var promoted_product = try matrix.mulPromote(f64, promoted_rhs);
            defer promoted_product.deinit();
            try expectFloatArray(promoted_product, &.{ 2, 3 }, &.{ 1, 0, 0, 0, -4, 10 });
            try matrix.mulPromoteOut(f64, promoted_rhs, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_product.data);

            var promoted_quotient = try matrix.divPromote(f64, promoted_rhs);
            defer promoted_quotient.deinit();
            try expectFloatArray(promoted_quotient, &.{ 2, 3 }, &.{ 4, 0, 0, 0, -0.25, 0.4 });
            try matrix.divPromoteOut(f64, promoted_rhs, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_quotient.data);

            var promoted_maximum = try matrix.maximumPromote(f64, promoted_rhs);
            defer promoted_maximum.deinit();
            try expectFloatArray(promoted_maximum, &.{ 2, 3 }, &.{ 2, 1, 2, 3, 4, 5 });
            try matrix.maximumPromoteOut(f64, promoted_rhs, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_maximum.data);

            var promoted_minimum = try matrix.minimumPromote(f64, promoted_rhs);
            defer promoted_minimum.deinit();
            try expectFloatArray(promoted_minimum, &.{ 2, 3 }, &.{ 0.5, 0, 0, 0, -1, 2 });
            try matrix.minimumPromoteOut(f64, promoted_rhs, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_minimum.data);

            var promoted_scalar_sum = try matrix.addScalarPromote(f64, 0.5);
            defer promoted_scalar_sum.deinit();
            try expectFloatArray(promoted_scalar_sum, &.{ 2, 3 }, &.{ 2.5, 0.5, 0.5, 0.5, -0.5, 2.5 });
            try matrix.addScalarPromoteOut(f64, 0.5, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_scalar_sum.data);

            var promoted_scalar_diff = try matrix.subScalarPromote(f64, 0.5);
            defer promoted_scalar_diff.deinit();
            try expectFloatArray(promoted_scalar_diff, &.{ 2, 3 }, &.{ 1.5, -0.5, -0.5, -0.5, -1.5, 1.5 });
            try matrix.subScalarPromoteOut(f64, 0.5, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_scalar_diff.data);

            var promoted_scalar_product = try matrix.mulScalarPromote(f64, 0.5);
            defer promoted_scalar_product.deinit();
            try expectFloatArray(promoted_scalar_product, &.{ 2, 3 }, &.{ 1, 0, 0, 0, -0.5, 1 });
            try matrix.mulScalarPromoteOut(f64, 0.5, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_scalar_product.data);

            var promoted_scalar_quotient = try matrix.divScalarPromote(f64, 0.5);
            defer promoted_scalar_quotient.deinit();
            try expectFloatArray(promoted_scalar_quotient, &.{ 2, 3 }, &.{ 4, 0, 0, 0, -2, 4 });
            try matrix.divScalarPromoteOut(f64, 0.5, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_scalar_quotient.data);

            var promoted_rsub_scalar = try matrix.rsubScalarPromote(f64, 0.5);
            defer promoted_rsub_scalar.deinit();
            try expectFloatArray(promoted_rsub_scalar, &.{ 2, 3 }, &.{ -1.5, 0.5, 0.5, 0.5, 1.5, -1.5 });
            try matrix.rsubScalarPromoteOut(f64, 0.5, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_rsub_scalar.data);

            var promoted_scalar_sub_alias = try matrix.scalarSubPromote(f64, 0.5);
            defer promoted_scalar_sub_alias.deinit();
            try expectFloatArray(promoted_scalar_sub_alias, &.{ 2, 3 }, promoted_rsub_scalar.data);
            try matrix.scalarSubPromoteOut(f64, 0.5, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_scalar_sub_alias.data);

            var promoted_rdiv_scalar = try matrix.rdivScalarPromote(f64, 2.0);
            defer promoted_rdiv_scalar.deinit();
            try expectFloatArray(promoted_rdiv_scalar, &.{ 2, 3 }, &.{ 1, std.math.inf(f64), std.math.inf(f64), std.math.inf(f64), -2, 1 });
            try matrix.rdivScalarPromoteOut(f64, 2.0, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_rdiv_scalar.data);

            var promoted_scalar_div_alias = try matrix.scalarDivPromote(f64, 2.0);
            defer promoted_scalar_div_alias.deinit();
            try expectFloatArray(promoted_scalar_div_alias, &.{ 2, 3 }, promoted_rdiv_scalar.data);
            try matrix.scalarDivPromoteOut(f64, 2.0, promoted_out);
            try expectFloatArray(promoted_out, &.{ 2, 3 }, promoted_scalar_div_alias.data);

            var rhs_sparse = try cooFromSlices(
                i32,
                matrix.allocator,
                2,
                3,
                &.{ 0, 0, 0, 1, 1, 1 },
                &.{ 0, 1, 2, 0, 1, 2 },
                &.{ 2, 2, 3, 4, 5, 2 },
            );
            defer rhs_sparse.deinit();
            var rhs_same_format = if (comptime Matrix == CooMatrix(i32))
                try rhs_sparse.clone()
            else if (comptime Matrix == CsrMatrix(i32))
                try rhs_sparse.toCsr()
            else if (comptime Matrix == CscMatrix(i32))
                try rhs_sparse.toCsc()
            else
                @compileError("unexpected sparse matrix format");
            defer rhs_same_format.deinit();

            var sparse_powers = try matrix.pow(rhs_same_format);
            defer sparse_powers.deinit();
            try expectArray(sparse_powers, &.{ 2, 3 }, &.{ 4, 0, 0, 0, -1, 4 });
            var sparse_binary_out = try array_mod.Array(i32).zeros(matrix.allocator, &.{ 2, 3 });
            defer sparse_binary_out.deinit();
            try matrix.powOut(rhs_same_format, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, sparse_powers.data);

            var sparse_floor = try matrix.floorDiv(rhs_same_format);
            defer sparse_floor.deinit();
            try expectArray(sparse_floor, &.{ 2, 3 }, &.{ 1, 0, 0, 0, -1, 1 });
            try matrix.floorDivOut(rhs_same_format, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, sparse_floor.data);

            var sparse_mod = try matrix.mod(rhs_same_format);
            defer sparse_mod.deinit();
            try expectArray(sparse_mod, &.{ 2, 3 }, &.{ 0, 0, 0, 0, 4, 0 });
            try matrix.modOut(rhs_same_format, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, sparse_mod.data);

            var sparse_remainder = try matrix.remainder(rhs_same_format);
            defer sparse_remainder.deinit();
            try expectArray(sparse_remainder, &.{ 2, 3 }, sparse_mod.data);
            try matrix.remainderOut(rhs_same_format, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, sparse_remainder.data);

            var sparse_maximum = try matrix.maximum(rhs_same_format);
            defer sparse_maximum.deinit();
            try expectArray(sparse_maximum, &.{ 2, 3 }, &.{ 2, 2, 3, 4, 5, 2 });
            try matrix.maximumOut(rhs_same_format, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, sparse_maximum.data);

            var sparse_minimum = try matrix.minimum(rhs_same_format);
            defer sparse_minimum.deinit();
            try expectArray(sparse_minimum, &.{ 2, 3 }, &.{ 2, 0, 0, 0, -1, 2 });
            try matrix.minimumOut(rhs_same_format, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, sparse_minimum.data);

            var sparse_fmax = try matrix.fmax(rhs_same_format);
            defer sparse_fmax.deinit();
            try expectArray(sparse_fmax, &.{ 2, 3 }, sparse_maximum.data);
            try matrix.fmaxOut(rhs_same_format, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, sparse_fmax.data);

            var sparse_fmin = try matrix.fmin(rhs_same_format);
            defer sparse_fmin.deinit();
            try expectArray(sparse_fmin, &.{ 2, 3 }, sparse_minimum.data);
            try matrix.fminOut(rhs_same_format, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, sparse_fmin.data);

            var bounds = try array_mod.Array(i32).fromSlice(matrix.allocator, &.{
                1, -1, 3,
                0, 4,  5,
            }, &.{ 2, 3 });
            defer bounds.deinit();
            var maximum = try matrix.maximumArray(bounds);
            defer maximum.deinit();
            try expectArray(maximum, &.{ 2, 3 }, &.{ 2, 0, 3, 0, 4, 5 });
            try matrix.maximumArrayOut(bounds, dense_binary_out);
            try expectArray(dense_binary_out, &.{ 2, 3 }, maximum.data);

            var minimum = try matrix.minimumArray(bounds);
            defer minimum.deinit();
            try expectArray(minimum, &.{ 2, 3 }, &.{ 1, -1, 0, 0, -1, 2 });
            try matrix.minimumArrayOut(bounds, dense_binary_out);
            try expectArray(dense_binary_out, &.{ 2, 3 }, minimum.data);

            var fmax = try matrix.fmaxArray(bounds);
            defer fmax.deinit();
            try expectArray(fmax, &.{ 2, 3 }, maximum.data);
            try matrix.fmaxArrayOut(bounds, dense_binary_out);
            try expectArray(dense_binary_out, &.{ 2, 3 }, fmax.data);

            var fmin = try matrix.fminArray(bounds);
            defer fmin.deinit();
            try expectArray(fmin, &.{ 2, 3 }, minimum.data);
            try matrix.fminArrayOut(bounds, dense_binary_out);
            try expectArray(dense_binary_out, &.{ 2, 3 }, fmin.data);

            var scalar_power = try matrix.powScalar(2);
            defer scalar_power.deinit();
            try expectArray(scalar_power, &.{ 2, 3 }, &.{ 4, 0, 0, 0, 1, 4 });
            try matrix.powScalarOut(2, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, scalar_power.data);

            var scalar_floored = try matrix.floorDivScalar(2);
            defer scalar_floored.deinit();
            try expectArray(scalar_floored, &.{ 2, 3 }, &.{ 1, 0, 0, 0, -1, 1 });
            try matrix.floorDivScalarOut(2, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, scalar_floored.data);

            var scalar_mod = try matrix.modScalar(2);
            defer scalar_mod.deinit();
            try expectArray(scalar_mod, &.{ 2, 3 }, &.{ 0, 0, 0, 0, 1, 0 });
            try matrix.modScalarOut(2, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, scalar_mod.data);

            var scalar_remainder = try matrix.remainderScalar(2);
            defer scalar_remainder.deinit();
            try expectArray(scalar_remainder, &.{ 2, 3 }, scalar_mod.data);
            try matrix.remainderScalarOut(2, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, scalar_remainder.data);

            var scalar_fmax = try matrix.fmaxScalar(1);
            defer scalar_fmax.deinit();
            try expectArray(scalar_fmax, &.{ 2, 3 }, &.{ 2, 1, 1, 1, 1, 2 });
            try matrix.fmaxScalarOut(1, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, scalar_fmax.data);

            var scalar_fmin = try matrix.fminScalar(1);
            defer scalar_fmin.deinit();
            try expectArray(scalar_fmin, &.{ 2, 3 }, &.{ 1, 0, 0, 0, -1, 1 });
            try matrix.fminScalarOut(1, sparse_binary_out);
            try expectArray(sparse_binary_out, &.{ 2, 3 }, scalar_fmin.data);

            var bad = try array_mod.Array(i32).ones(matrix.allocator, &.{ 3, 2 });
            defer bad.deinit();
            try std.testing.expectError(error.ShapeMismatch, matrix.powArray(bad));
            try std.testing.expectError(error.ShapeMismatch, matrix.floorDivArray(bad));
            try std.testing.expectError(error.ShapeMismatch, matrix.modArray(bad));
            try std.testing.expectError(error.ShapeMismatch, matrix.remainderArray(bad));
            var bad_promoted = try array_mod.Array(f64).ones(matrix.allocator, &.{ 3, 2 });
            defer bad_promoted.deinit();
            try std.testing.expectError(error.ShapeMismatch, matrix.addPromote(f64, bad_promoted));
            try std.testing.expectError(error.ShapeMismatch, matrix.subPromote(f64, bad_promoted));
            try std.testing.expectError(error.ShapeMismatch, matrix.mulPromote(f64, bad_promoted));
            try std.testing.expectError(error.ShapeMismatch, matrix.divPromote(f64, bad_promoted));
            try std.testing.expectError(error.ShapeMismatch, matrix.maximumPromote(f64, bad_promoted));
            try std.testing.expectError(error.ShapeMismatch, matrix.minimumPromote(f64, bad_promoted));
            try std.testing.expectError(error.ShapeMismatch, matrix.maximumArray(bad));
            try std.testing.expectError(error.ShapeMismatch, matrix.minimumArray(bad));
            try std.testing.expectError(error.ShapeMismatch, matrix.fmaxArray(bad));
            try std.testing.expectError(error.ShapeMismatch, matrix.fminArray(bad));

            var bad_sparse_coo = try cooFromSlices(i32, matrix.allocator, 3, 2, &.{0}, &.{0}, &.{1});
            defer bad_sparse_coo.deinit();
            var bad_same_format = if (comptime Matrix == CooMatrix(i32))
                try bad_sparse_coo.clone()
            else if (comptime Matrix == CsrMatrix(i32))
                try bad_sparse_coo.toCsr()
            else if (comptime Matrix == CscMatrix(i32))
                try bad_sparse_coo.toCsc()
            else
                @compileError("unexpected sparse matrix format");
            defer bad_same_format.deinit();
            try std.testing.expectError(error.ShapeMismatch, matrix.pow(bad_same_format));
            try std.testing.expectError(error.ShapeMismatch, matrix.floorDiv(bad_same_format));
            try std.testing.expectError(error.ShapeMismatch, matrix.mod(bad_same_format));
            try std.testing.expectError(error.ShapeMismatch, matrix.remainder(bad_same_format));
            try std.testing.expectError(error.ShapeMismatch, matrix.maximum(bad_same_format));
            try std.testing.expectError(error.ShapeMismatch, matrix.minimum(bad_same_format));
            try std.testing.expectError(error.ShapeMismatch, matrix.fmax(bad_same_format));
            try std.testing.expectError(error.ShapeMismatch, matrix.fmin(bad_same_format));
        }
    }.check;

    var matrix = try cooFromSlices(i32, gpa, 2, 3, &.{ 0, 1, 1 }, &.{ 0, 1, 2 }, &.{ 2, -1, 2 });
    defer matrix.deinit();
    try expectNumericArrays(@TypeOf(matrix), matrix);
    var matrix_csr = try matrix.toCsr();
    defer matrix_csr.deinit();
    try expectNumericArrays(@TypeOf(matrix_csr), matrix_csr);
    var matrix_csc = try matrix.toCsc();
    defer matrix_csc.deinit();
    try expectNumericArrays(@TypeOf(matrix_csc), matrix_csc);
}

test "sparse dense reduction helpers" {
    const gpa = std.testing.allocator;

    const expectReductions = struct {
        fn expectArray(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            for (expected, values.data) |want, got| {
                if (std.math.isInf(want) or std.math.isInf(got)) {
                    try std.testing.expectEqual(want, got);
                } else if (std.math.isNan(want) or std.math.isNan(got)) {
                    try std.testing.expect(std.math.isNan(want) and std.math.isNan(got));
                } else {
                    try std.testing.expectApproxEqAbs(want, got, 1e-12);
                }
            }
        }

        fn check(comptime Matrix: type, matrix: Matrix) !void {
            // The legacy sparse sum() API intentionally remains a stored-value
            // scalar reduction; axis-aware sum helpers below mirror dense Array
            // semantics after materializing implicit zeros.
            try std.testing.expectEqual(@as(f64, 6), matrix.sum());

            var row_sum = try matrix.sumDim(1, false);
            defer row_sum.deinit();
            try expectArray(row_sum, &.{2}, &.{ 1, 5 });
            var row_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{2});
            defer row_out.deinit();
            try matrix.sumDimOut(1, false, row_out);
            try expectArray(row_out, &.{2}, row_sum.data);

            var column_sum = try matrix.sumDim(0, false);
            defer column_sum.deinit();
            try expectArray(column_sum, &.{3}, &.{ 1, 2, 3 });
            var column_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{3});
            defer column_out.deinit();
            try matrix.sumDimOut(0, false, column_out);
            try expectArray(column_out, &.{3}, column_sum.data);

            var all_sum_keep = try matrix.sumAxes(&.{ 0, 1 }, true);
            defer all_sum_keep.deinit();
            try expectArray(all_sum_keep, &.{ 1, 1 }, &.{6});
            var keepdim_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 1, 1 });
            defer keepdim_out.deinit();
            try matrix.sumAxesOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_sum_keep.data);

            var all_sum_dims = try matrix.sumDims(&.{ 0, 1 }, false);
            defer all_sum_dims.deinit();
            try expectArray(all_sum_dims, &.{}, all_sum_keep.data);
            var scalar_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{});
            defer scalar_out.deinit();
            try matrix.sumDimsOut(&.{ 0, 1 }, false, scalar_out);
            try expectArray(scalar_out, &.{}, all_sum_dims.data);

            var row_sums_to_size = try matrix.sumToSize(&.{ 2, 1 });
            defer row_sums_to_size.deinit();
            try expectArray(row_sums_to_size, &.{ 2, 1 }, &.{ 1, 5 });
            var row_to_size_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 1 });
            defer row_to_size_out.deinit();
            try matrix.sumToSizeOut(&.{ 2, 1 }, row_to_size_out);
            try expectArray(row_to_size_out, &.{ 2, 1 }, row_sums_to_size.data);

            var column_sums_to_size = try matrix.sumToSize(&.{ 1, 3 });
            defer column_sums_to_size.deinit();
            try expectArray(column_sums_to_size, &.{ 1, 3 }, column_sum.data);
            var column_to_size_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 1, 3 });
            defer column_to_size_out.deinit();
            try matrix.sumToSizeOut(&.{ 1, 3 }, column_to_size_out);
            try expectArray(column_to_size_out, &.{ 1, 3 }, column_sums_to_size.data);

            var flat_sum_to_size = try matrix.sumToSize(&.{});
            defer flat_sum_to_size.deinit();
            try expectArray(flat_sum_to_size, &.{}, all_sum_dims.data);
            try matrix.sumToSizeOut(&.{}, scalar_out);
            try expectArray(scalar_out, &.{}, flat_sum_to_size.data);

            var flat_product = try matrix.prod(null, false);
            defer flat_product.deinit();
            try expectArray(flat_product, &.{}, &.{0});
            try matrix.prodOut(null, false, scalar_out);
            try expectArray(scalar_out, &.{}, flat_product.data);

            var row_product = try matrix.prod(1, false);
            defer row_product.deinit();
            try expectArray(row_product, &.{2}, &.{ 0, 0 });
            try matrix.prodOut(1, false, row_out);
            try expectArray(row_out, &.{2}, row_product.data);

            var column_product_keep = try matrix.prodDim(0, true);
            defer column_product_keep.deinit();
            try expectArray(column_product_keep, &.{ 1, 3 }, &.{ 0, 0, 0 });
            try matrix.prodDimOut(0, true, column_to_size_out);
            try expectArray(column_to_size_out, &.{ 1, 3 }, column_product_keep.data);

            var all_product_keep = try matrix.prodAxes(&.{ 0, 1 }, true);
            defer all_product_keep.deinit();
            try expectArray(all_product_keep, &.{ 1, 1 }, &.{0});
            try matrix.prodAxesOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_product_keep.data);

            var row_product_dims = try matrix.prodDims(&.{1}, false);
            defer row_product_dims.deinit();
            try expectArray(row_product_dims, &.{2}, row_product.data);
            try matrix.prodDimsOut(&.{1}, false, row_out);
            try expectArray(row_out, &.{2}, row_product_dims.data);

            var flat_min = try matrix.min(null, false);
            defer flat_min.deinit();
            try expectArray(flat_min, &.{}, &.{0});
            try matrix.minOut(null, false, scalar_out);
            try expectArray(scalar_out, &.{}, flat_min.data);
            try matrix.aminOut(null, false, scalar_out);
            try expectArray(scalar_out, &.{}, flat_min.data);

            var row_min = try matrix.amin(1, false);
            defer row_min.deinit();
            try expectArray(row_min, &.{2}, &.{ 0, 0 });
            try matrix.aminOut(1, false, row_out);
            try expectArray(row_out, &.{2}, row_min.data);

            var column_min_keep = try matrix.minDim(0, true);
            defer column_min_keep.deinit();
            try expectArray(column_min_keep, &.{ 1, 3 }, &.{ 0, 0, 0 });
            try matrix.minDimOut(0, true, column_to_size_out);
            try expectArray(column_to_size_out, &.{ 1, 3 }, column_min_keep.data);
            try matrix.aminDimOut(0, true, column_to_size_out);
            try expectArray(column_to_size_out, &.{ 1, 3 }, column_min_keep.data);

            var all_min_keep = try matrix.minAxes(&.{ 0, 1 }, true);
            defer all_min_keep.deinit();
            try expectArray(all_min_keep, &.{ 1, 1 }, &.{0});
            try matrix.minAxesOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_min_keep.data);
            try matrix.aminAxesOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_min_keep.data);

            var row_min_dims = try matrix.aminDims(&.{1}, false);
            defer row_min_dims.deinit();
            try expectArray(row_min_dims, &.{2}, row_min.data);
            try matrix.minDimsOut(&.{1}, false, row_out);
            try expectArray(row_out, &.{2}, row_min_dims.data);
            try matrix.aminDimsOut(&.{1}, false, row_out);
            try expectArray(row_out, &.{2}, row_min_dims.data);

            var flat_max = try matrix.max(null, false);
            defer flat_max.deinit();
            try expectArray(flat_max, &.{}, &.{3});
            try matrix.maxOut(null, false, scalar_out);
            try expectArray(scalar_out, &.{}, flat_max.data);
            try matrix.amaxOut(null, false, scalar_out);
            try expectArray(scalar_out, &.{}, flat_max.data);

            var row_max = try matrix.amax(1, false);
            defer row_max.deinit();
            try expectArray(row_max, &.{2}, &.{ 1, 3 });
            try matrix.amaxOut(1, false, row_out);
            try expectArray(row_out, &.{2}, row_max.data);

            var column_max_keep = try matrix.maxDim(0, true);
            defer column_max_keep.deinit();
            try expectArray(column_max_keep, &.{ 1, 3 }, &.{ 1, 2, 3 });
            try matrix.maxDimOut(0, true, column_to_size_out);
            try expectArray(column_to_size_out, &.{ 1, 3 }, column_max_keep.data);
            try matrix.amaxDimOut(0, true, column_to_size_out);
            try expectArray(column_to_size_out, &.{ 1, 3 }, column_max_keep.data);

            var all_max_keep = try matrix.maxAxes(&.{ 0, 1 }, true);
            defer all_max_keep.deinit();
            try expectArray(all_max_keep, &.{ 1, 1 }, &.{3});
            try matrix.maxAxesOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_max_keep.data);
            try matrix.amaxAxesOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_max_keep.data);

            var column_max_dims = try matrix.amaxDims(&.{0}, false);
            defer column_max_dims.deinit();
            try expectArray(column_max_dims, &.{3}, column_max_keep.data);
            try matrix.maxDimsOut(&.{0}, false, column_out);
            try expectArray(column_out, &.{3}, column_max_dims.data);
            try matrix.amaxDimsOut(&.{0}, false, column_out);
            try expectArray(column_out, &.{3}, column_max_dims.data);

            var flat_ptp = try matrix.ptp(null, false);
            defer flat_ptp.deinit();
            try expectArray(flat_ptp, &.{}, &.{3});
            try matrix.ptpOut(null, false, scalar_out);
            try expectArray(scalar_out, &.{}, flat_ptp.data);

            var row_ptp = try matrix.ptp(1, false);
            defer row_ptp.deinit();
            try expectArray(row_ptp, &.{2}, &.{ 1, 3 });
            try matrix.ptpOut(1, false, row_out);
            try expectArray(row_out, &.{2}, row_ptp.data);

            var column_ptp_keep = try matrix.ptpDim(0, true);
            defer column_ptp_keep.deinit();
            try expectArray(column_ptp_keep, &.{ 1, 3 }, &.{ 1, 2, 3 });
            try matrix.ptpDimOut(0, true, column_to_size_out);
            try expectArray(column_to_size_out, &.{ 1, 3 }, column_ptp_keep.data);

            var all_ptp_keep = try matrix.ptpAxes(&.{ 0, 1 }, true);
            defer all_ptp_keep.deinit();
            try expectArray(all_ptp_keep, &.{ 1, 1 }, &.{3});
            try matrix.ptpAxesOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_ptp_keep.data);

            var row_ptp_dims = try matrix.ptpDims(&.{1}, false);
            defer row_ptp_dims.deinit();
            try expectArray(row_ptp_dims, &.{2}, row_ptp.data);
            try matrix.ptpDimsOut(&.{1}, false, row_out);
            try expectArray(row_out, &.{2}, row_ptp_dims.data);

            var row_mean = try matrix.meanDim(1, false);
            defer row_mean.deinit();
            try expectArray(row_mean, &.{2}, &.{ 1.0 / 3.0, 5.0 / 3.0 });
            try matrix.meanDimOut(1, false, row_out);
            try expectArray(row_out, &.{2}, row_mean.data);

            var column_mean_keep = try matrix.meanDim(0, true);
            defer column_mean_keep.deinit();
            try expectArray(column_mean_keep, &.{ 1, 3 }, &.{ 0.5, 1, 1.5 });
            try matrix.meanDimOut(0, true, column_to_size_out);
