            var all_mean_keep = try matrix.meanAxes(&.{ 0, 1 }, true);
            defer all_mean_keep.deinit();
            try expectArray(all_mean_keep, &.{ 1, 1 }, &.{1});
            try matrix.meanAxesOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_mean_keep.data);

            var row_mean_dims = try matrix.meanDims(&.{1}, false);
            defer row_mean_dims.deinit();
            try expectArray(row_mean_dims, &.{2}, row_mean.data);
            try matrix.meanDimsOut(&.{1}, false, row_out);
            try expectArray(row_out, &.{2}, row_mean_dims.data);

            var row_variance = try matrix.varianceDim(1, false, 0);
            defer row_variance.deinit();
            try expectArray(row_variance, &.{2}, &.{ 2.0 / 9.0, 14.0 / 9.0 });
            try matrix.varianceDimOut(1, false, 0, row_out);
            try expectArray(row_out, &.{2}, row_variance.data);
            try matrix.varDimOut(1, false, 0, row_out);
            try expectArray(row_out, &.{2}, row_variance.data);

            var column_variance_keep = try matrix.varDim(0, true, 0);
            defer column_variance_keep.deinit();
            try expectArray(column_variance_keep, &.{ 1, 3 }, &.{ 0.25, 1, 2.25 });
            try matrix.varianceDimOut(0, true, 0, column_to_size_out);
            try expectArray(column_to_size_out, &.{ 1, 3 }, column_variance_keep.data);

            var all_variance_keep = try matrix.varianceAxes(&.{ 0, 1 }, true, 0);
            defer all_variance_keep.deinit();
            try expectArray(all_variance_keep, &.{ 1, 1 }, &.{4.0 / 3.0});
            try matrix.varianceAxesOut(&.{ 0, 1 }, true, 0, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_variance_keep.data);
            try matrix.varAxesOut(&.{ 0, 1 }, true, 0, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_variance_keep.data);

            var row_variance_dims = try matrix.varDims(&.{1}, false, 0);
            defer row_variance_dims.deinit();
            try expectArray(row_variance_dims, &.{2}, row_variance.data);
            try matrix.varianceDimsOut(&.{1}, false, 0, row_out);
            try expectArray(row_out, &.{2}, row_variance_dims.data);
            try matrix.varDimsOut(&.{1}, false, 0, row_out);
            try expectArray(row_out, &.{2}, row_variance_dims.data);

            var row_std = try matrix.stddevDim(1, false, 0);
            defer row_std.deinit();
            try expectArray(row_std, &.{2}, &.{ @sqrt(2.0 / 9.0), @sqrt(14.0 / 9.0) });
            try matrix.stddevDimOut(1, false, 0, row_out);
            try expectArray(row_out, &.{2}, row_std.data);
            try matrix.stdDimOut(1, false, 0, row_out);
            try expectArray(row_out, &.{2}, row_std.data);

            var column_std_keep = try matrix.stdDim(0, true, 0);
            defer column_std_keep.deinit();
            try expectArray(column_std_keep, &.{ 1, 3 }, &.{ 0.5, 1, 1.5 });
            try matrix.stddevDimOut(0, true, 0, column_to_size_out);
            try expectArray(column_to_size_out, &.{ 1, 3 }, column_std_keep.data);

            var all_std_keep = try matrix.stddevAxes(&.{ 0, 1 }, true, 0);
            defer all_std_keep.deinit();
            try expectArray(all_std_keep, &.{ 1, 1 }, &.{@sqrt(4.0 / 3.0)});
            try matrix.stddevAxesOut(&.{ 0, 1 }, true, 0, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_std_keep.data);
            try matrix.stdAxesOut(&.{ 0, 1 }, true, 0, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_std_keep.data);

            var row_std_dims = try matrix.stdDims(&.{1}, false, 0);
            defer row_std_dims.deinit();
            try expectArray(row_std_dims, &.{2}, row_std.data);
            try matrix.stddevDimsOut(&.{1}, false, 0, row_out);
            try expectArray(row_out, &.{2}, row_std_dims.data);
            try matrix.stdDimsOut(&.{1}, false, 0, row_out);
            try expectArray(row_out, &.{2}, row_std_dims.data);

            try std.testing.expectError(error.InvalidAxis, matrix.sumDim(2, false));
            try std.testing.expectError(error.InvalidAxis, matrix.prod(2, false));
            try std.testing.expectError(error.InvalidAxis, matrix.min(2, false));
            try std.testing.expectError(error.InvalidAxis, matrix.max(2, false));
            try std.testing.expectError(error.InvalidAxis, matrix.ptp(2, false));
            try std.testing.expectError(error.InvalidAxis, matrix.meanDim(2, false));
            try std.testing.expectError(error.InvalidAxis, matrix.varianceDim(2, false, 0));
            try std.testing.expectError(error.InvalidAxis, matrix.stddevDim(2, false, 0));
            try std.testing.expectError(error.ShapeMismatch, matrix.sumToSize(&.{ 2, 2 }));
        }
    }.check;

    var matrix = try cooFromSlices(f64, gpa, 2, 3, &.{ 0, 1, 1 }, &.{ 0, 1, 2 }, &.{ 1, 2, 3 });
    defer matrix.deinit();
    try expectReductions(@TypeOf(matrix), matrix);
    var matrix_csr = try matrix.toCsr();
    defer matrix_csr.deinit();
    try expectReductions(@TypeOf(matrix_csr), matrix_csr);
    var matrix_csc = try matrix.toCsc();
    defer matrix_csc.deinit();
    try expectReductions(@TypeOf(matrix_csc), matrix_csc);
}

test "sparse dense norm and logsumexp helpers" {
    const gpa = std.testing.allocator;

    const expectNorms = struct {
        fn expectArray(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            for (expected, values.data) |want, got| {
                if (std.math.isInf(want) or std.math.isInf(got)) {
                    try std.testing.expectEqual(want, got);
                } else if (std.math.isNan(want) or std.math.isNan(got)) {
                    try std.testing.expect(std.math.isNan(want) and std.math.isNan(got));
                } else {
                    try std.testing.expectApproxEqAbs(want, got, 1e-12);
                }
            }
        }

        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var flat_l1 = try matrix.norm(1, null, false);
            defer flat_l1.deinit();
            try expectArray(flat_l1, &.{}, &.{6});
            var norm_scalar_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{});
            defer norm_scalar_out.deinit();
            try matrix.normOut(1, null, false, norm_scalar_out);
            try expectArray(norm_scalar_out, &.{}, flat_l1.data);

            var row_l2 = try matrix.norm(2, 1, false);
            defer row_l2.deinit();
            try expectArray(row_l2, &.{2}, &.{ 1, @sqrt(@as(f64, 13)) });
            var norm_row_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{2});
            defer norm_row_out.deinit();
            try matrix.normOut(2, 1, false, norm_row_out);
            try expectArray(norm_row_out, &.{2}, row_l2.data);

            var row_l2_keep = try matrix.normDim(2, -1, true);
            defer row_l2_keep.deinit();
            try expectArray(row_l2_keep, &.{ 2, 1 }, row_l2.data);
            var norm_row_keep_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 1 });
            defer norm_row_keep_out.deinit();
            try matrix.normDimOut(2, -1, true, norm_row_keep_out);
            try expectArray(norm_row_keep_out, &.{ 2, 1 }, row_l2_keep.data);

            var all_axes_l2 = try matrix.normAxes(2, &.{ 0, 1 }, true);
            defer all_axes_l2.deinit();
            try expectArray(all_axes_l2, &.{ 1, 1 }, &.{@sqrt(@as(f64, 14))});
            var norm_all_keep_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 1, 1 });
            defer norm_all_keep_out.deinit();
            try matrix.normAxesOut(2, &.{ 0, 1 }, true, norm_all_keep_out);
            try expectArray(norm_all_keep_out, &.{ 1, 1 }, all_axes_l2.data);

            var all_axes_l1 = try matrix.normDims(1, &.{ 0, 1 }, false);
            defer all_axes_l1.deinit();
            try expectArray(all_axes_l1, &.{}, flat_l1.data);
            try matrix.normDimsOut(1, &.{ 0, 1 }, false, norm_scalar_out);
            try expectArray(norm_scalar_out, &.{}, all_axes_l1.data);

            var exp_values = try matrix.exp();
            defer exp_values.deinit();
            try expectArray(exp_values, &.{ 2, 3 }, &.{
                std.math.exp(@as(f64, 1)),
                1,
                1,
                1,
                std.math.exp(@as(f64, 2)),
                std.math.exp(@as(f64, 3)),
            });
            var unary_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer unary_out.deinit();
            try matrix.expOut(unary_out);
            try expectArray(unary_out, &.{ 2, 3 }, exp_values.data);

            var exp2_values = try matrix.exp2();
            defer exp2_values.deinit();
            try expectArray(exp2_values, &.{ 2, 3 }, &.{ 2, 1, 1, 1, 4, 8 });
            try matrix.exp2Out(unary_out);
            try expectArray(unary_out, &.{ 2, 3 }, exp2_values.data);

            var expm1_values = try matrix.expm1();
            defer expm1_values.deinit();
            try expectArray(expm1_values, &.{ 2, 3 }, &.{
                std.math.exp(@as(f64, 1)) - 1,
                0,
                0,
                0,
                std.math.exp(@as(f64, 2)) - 1,
                std.math.exp(@as(f64, 3)) - 1,
            });
            try matrix.expm1Out(unary_out);
            try expectArray(unary_out, &.{ 2, 3 }, expm1_values.data);

            var log_values = try matrix.log();
            defer log_values.deinit();
