                @as(f64, 0.5) * @as(f64, -2) * (1 + std.math.tanh(@sqrt(@as(f64, 2.0) / std.math.pi) * (@as(f64, -2) + @as(f64, 0.044715) * @as(f64, -8)))),
                0,
                0,
                0,
                @as(f64, 0.5) * @as(f64, 0.5) * (1 + std.math.tanh(@sqrt(@as(f64, 2.0) / std.math.pi) * (@as(f64, 0.5) + @as(f64, 0.044715) * @as(f64, 0.125)))),
                @as(f64, 0.5) * @as(f64, 7) * (1 + std.math.tanh(@sqrt(@as(f64, 2.0) / std.math.pi) * (@as(f64, 7) + @as(f64, 0.044715) * @as(f64, 343)))),
            });
            try activation_matrix.geluOut(unary_out);
            try expectArray(unary_out, &.{ 2, 3 }, gelu_values.data);

            var hard_sigmoid_values = try activation_matrix.hardsigmoid();
            defer hard_sigmoid_values.deinit();
            try expectArray(hard_sigmoid_values, &.{ 2, 3 }, &.{ 1.0 / 6.0, 0.5, 0.5, 0.5, 3.5 / 6.0, 1 });
            try activation_matrix.hardsigmoidOut(unary_out);
            try expectArray(unary_out, &.{ 2, 3 }, hard_sigmoid_values.data);

            var hard_sigmoid_alias = try activation_matrix.hardSigmoid();
            defer hard_sigmoid_alias.deinit();
            try expectArray(hard_sigmoid_alias, &.{ 2, 3 }, hard_sigmoid_values.data);
            try activation_matrix.hardSigmoidOut(unary_out);
            try expectArray(unary_out, &.{ 2, 3 }, hard_sigmoid_alias.data);

            var hard_swish_values = try activation_matrix.hardswish();
            defer hard_swish_values.deinit();
            try expectArray(hard_swish_values, &.{ 2, 3 }, &.{ -2.0 / 6.0, 0, 0, 0, 0.5 * 3.5 / 6.0, 7 });
            try activation_matrix.hardswishOut(unary_out);
            try expectArray(unary_out, &.{ 2, 3 }, hard_swish_values.data);

            var hard_swish_alias = try activation_matrix.hardSwish();
            defer hard_swish_alias.deinit();
            try expectArray(hard_swish_alias, &.{ 2, 3 }, hard_swish_values.data);
            try activation_matrix.hardSwishOut(unary_out);
            try expectArray(unary_out, &.{ 2, 3 }, hard_swish_alias.data);

            var log_sigmoid_values = try activation_matrix.logsigmoid();
            defer log_sigmoid_values.deinit();
            try expectArray(log_sigmoid_values, &.{ 2, 3 }, &.{ -(@as(f64, 2) + std.math.log1p(std.math.exp(@as(f64, -2)))), -std.math.log1p(@as(f64, 1)), -std.math.log1p(@as(f64, 1)), -std.math.log1p(@as(f64, 1)), -std.math.log1p(std.math.exp(@as(f64, -0.5))), -std.math.log1p(std.math.exp(@as(f64, -7))) });
            try activation_matrix.logsigmoidOut(unary_out);
            try expectArray(unary_out, &.{ 2, 3 }, log_sigmoid_values.data);

            var log_sigmoid_alias = try activation_matrix.logSigmoid();
            defer log_sigmoid_alias.deinit();
            try expectArray(log_sigmoid_alias, &.{ 2, 3 }, log_sigmoid_values.data);
            try activation_matrix.logSigmoidOut(unary_out);
            try expectArray(unary_out, &.{ 2, 3 }, log_sigmoid_alias.data);

            var glu_source = try cooFromSlices(
                f64,
                matrix.allocator,
                2,
                4,
                &.{ 0, 0, 0, 0, 1, 1, 1, 1 },
                &.{ 0, 1, 2, 3, 0, 1, 2, 3 },
                &.{ 1, 2, -1, 0.5, 3, 4, 1, -2 },
            );
            defer glu_source.deinit();
            var glu_matrix = if (comptime Matrix == CooMatrix(f64))
                try glu_source.clone()
            else if (comptime Matrix == CsrMatrix(f64))
                try glu_source.toCsr()
            else if (comptime Matrix == CscMatrix(f64))
                try glu_source.toCsc()
            else
                @compileError("unexpected sparse matrix format");
            defer glu_matrix.deinit();

            var glu_values = try glu_matrix.glu(1);
            defer glu_values.deinit();
            try expectArray(glu_values, &.{ 2, 2 }, &.{
                1.0 / (1.0 + std.math.exp(@as(f64, 1))),
                2.0 / (1.0 + std.math.exp(@as(f64, -0.5))),
                3.0 / (1.0 + std.math.exp(@as(f64, -1))),
                4.0 / (1.0 + std.math.exp(@as(f64, 2))),
            });
            var glu_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 2 });
            defer glu_out.deinit();
            try glu_matrix.gluOut(1, glu_out);
            try expectArray(glu_out, &.{ 2, 2 }, glu_values.data);

            var glu_dim_alias = try glu_matrix.gluDim(-1);
            defer glu_dim_alias.deinit();
            try expectArray(glu_dim_alias, &.{ 2, 2 }, glu_values.data);
            try glu_matrix.gluDimOut(-1, glu_out);
            try expectArray(glu_out, &.{ 2, 2 }, glu_dim_alias.data);

            try std.testing.expectError(error.InvalidShape, activation_matrix.glu(1));

            var logit_source = try cooFromSlices(f64, matrix.allocator, 2, 3, &.{ 0, 1, 1 }, &.{ 0, 1, 2 }, &.{ 0.25, 0.5, 0.75 });
            defer logit_source.deinit();
            var logit_matrix = if (comptime Matrix == CooMatrix(f64))
                try logit_source.clone()
            else if (comptime Matrix == CsrMatrix(f64))
                try logit_source.toCsr()
            else if (comptime Matrix == CscMatrix(f64))
                try logit_source.toCsc()
            else
                @compileError("unexpected sparse matrix format");
            defer logit_matrix.deinit();
            var logit_values = try logit_matrix.logit();
            defer logit_values.deinit();
            try expectArray(logit_values, &.{ 2, 3 }, &.{ std.math.log(f64, std.math.e, 0.25 / 0.75), -std.math.inf(f64), -std.math.inf(f64), -std.math.inf(f64), 0, std.math.log(f64, std.math.e, 0.75 / 0.25) });
            try logit_matrix.logitOut(unary_out);
            try expectArray(unary_out, &.{ 2, 3 }, logit_values.data);

            var row_lse = try matrix.logsumexp(1, false);
            defer row_lse.deinit();
            try expectArray(row_lse, &.{2}, &.{
                std.math.log(f64, std.math.e, std.math.exp(@as(f64, 1)) + 2),
                std.math.log(f64, std.math.e, 1 + std.math.exp(@as(f64, 2)) + std.math.exp(@as(f64, 3))),
            });
            var row_lse_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{2});
            defer row_lse_out.deinit();
            try matrix.logsumexpOut(1, false, row_lse_out);
            try expectArray(row_lse_out, &.{2}, row_lse.data);

            var row_lse_dim = try matrix.logsumexpDim(-1, true);
            defer row_lse_dim.deinit();
            try expectArray(row_lse_dim, &.{ 2, 1 }, row_lse.data);
            var row_lse_keepdim_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 1 });
            defer row_lse_keepdim_out.deinit();
            try matrix.logsumexpDimOut(-1, true, row_lse_keepdim_out);
            try expectArray(row_lse_keepdim_out, &.{ 2, 1 }, row_lse_dim.data);

            var all_lse = try matrix.logsumexpAxes(&.{ 0, 1 }, false);
            defer all_lse.deinit();
            try expectArray(all_lse, &.{}, &.{std.math.log(f64, std.math.e, std.math.exp(@as(f64, 1)) + std.math.exp(@as(f64, 2)) + std.math.exp(@as(f64, 3)) + 3)});
            var all_lse_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{});
            defer all_lse_out.deinit();
            try matrix.logsumexpAxesOut(&.{ 0, 1 }, false, all_lse_out);
            try expectArray(all_lse_out, &.{}, all_lse.data);

            var all_lse_keep = try matrix.logsumexpDims(&.{ 0, 1 }, true);
            defer all_lse_keep.deinit();
            try expectArray(all_lse_keep, &.{ 1, 1 }, all_lse.data);
            var all_lse_keep_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 1, 1 });
            defer all_lse_keep_out.deinit();
            try matrix.logsumexpDimsOut(&.{ 0, 1 }, true, all_lse_keep_out);
            try expectArray(all_lse_keep_out, &.{ 1, 1 }, all_lse_keep.data);

            var softmax_rows = try matrix.softmax(1);
            defer softmax_rows.deinit();
            var softmax_row_sums = try softmax_rows.sum(1, false);
            defer softmax_row_sums.deinit();
            try expectArray(softmax_row_sums, &.{2}, &.{ 1, 1 });
            var softmax_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer softmax_out.deinit();
            try matrix.softmaxOut(1, softmax_out);
            try expectArray(softmax_out, &.{ 2, 3 }, softmax_rows.data);

            var softmax_rows_dim = try matrix.softmaxDim(-1);
            defer softmax_rows_dim.deinit();
            try expectArray(softmax_rows_dim, &.{ 2, 3 }, softmax_rows.data);
            try matrix.softmaxDimOut(-1, softmax_out);
            try expectArray(softmax_out, &.{ 2, 3 }, softmax_rows_dim.data);

            var softmin_rows = try matrix.softmin(1);
            defer softmin_rows.deinit();
            var negated = try matrix.neg();
            defer negated.deinit();
            var expected_softmin = try negated.softmax(1);
            defer expected_softmin.deinit();
            try expectArray(softmin_rows, &.{ 2, 3 }, expected_softmin.data);
            try matrix.softminOut(1, softmax_out);
            try expectArray(softmax_out, &.{ 2, 3 }, softmin_rows.data);

            var softmin_rows_dim = try matrix.softminDim(-1);
            defer softmin_rows_dim.deinit();
            try expectArray(softmin_rows_dim, &.{ 2, 3 }, softmin_rows.data);
            try matrix.softminDimOut(-1, softmax_out);
            try expectArray(softmax_out, &.{ 2, 3 }, softmin_rows_dim.data);

            var log_softmax_rows = try matrix.logSoftmax(1);
            defer log_softmax_rows.deinit();
            var log_softmax_probs = try log_softmax_rows.exp();
            defer log_softmax_probs.deinit();
            var log_softmax_row_sums = try log_softmax_probs.sum(1, false);
            defer log_softmax_row_sums.deinit();
            try expectArray(log_softmax_row_sums, &.{2}, &.{ 1, 1 });
            try matrix.logSoftmaxOut(1, softmax_out);
            try expectArray(softmax_out, &.{ 2, 3 }, log_softmax_rows.data);

            var log_softmax_dim = try matrix.logSoftmaxDim(-1);
            defer log_softmax_dim.deinit();
            try expectArray(log_softmax_dim, &.{ 2, 3 }, log_softmax_rows.data);
            try matrix.logSoftmaxDimOut(-1, softmax_out);
            try expectArray(softmax_out, &.{ 2, 3 }, log_softmax_dim.data);

            var log_softmin_rows = try matrix.logSoftmin(1);
            defer log_softmin_rows.deinit();
            var expected_log_softmin = try negated.logSoftmax(1);
            defer expected_log_softmin.deinit();
            try expectArray(log_softmin_rows, &.{ 2, 3 }, expected_log_softmin.data);
            try matrix.logSoftminOut(1, softmax_out);
            try expectArray(softmax_out, &.{ 2, 3 }, log_softmin_rows.data);

            var log_softmin_dim = try matrix.logSoftminDim(-1);
            defer log_softmin_dim.deinit();
            try expectArray(log_softmin_dim, &.{ 2, 3 }, log_softmin_rows.data);
            try matrix.logSoftminDimOut(-1, softmax_out);
            try expectArray(softmax_out, &.{ 2, 3 }, log_softmin_dim.data);

            var normalized_rows = try matrix.normalize(2, 1, 1e-12);
            defer normalized_rows.deinit();
            try expectArray(normalized_rows, &.{ 2, 3 }, &.{ 1, 0, 0, 0, 2.0 / @sqrt(@as(f64, 13)), 3.0 / @sqrt(@as(f64, 13)) });
            try matrix.normalizeOut(2, 1, 1e-12, softmax_out);
            try expectArray(softmax_out, &.{ 2, 3 }, normalized_rows.data);

            var other = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{
                1, 1, 0,
                0, 2, 6,
            }, &.{ 2, 3 });
            defer other.deinit();
            var cosine_rows = try matrix.cosineSimilarity(other, 1, 1e-12, false);
            defer cosine_rows.deinit();
            try expectArray(cosine_rows, &.{2}, &.{ 1.0 / @sqrt(@as(f64, 2)), 22.0 / @sqrt(@as(f64, 520)) });
            try matrix.cosineSimilarityOut(other, 1, 1e-12, false, row_lse_out);
            try expectArray(row_lse_out, &.{2}, cosine_rows.data);

            var cosine_rows_keep = try matrix.cosineSimilarityDim(other, -1, 1e-12, true);
            defer cosine_rows_keep.deinit();
            try expectArray(cosine_rows_keep, &.{ 2, 1 }, cosine_rows.data);
            try matrix.cosineSimilarityDimOut(other, -1, 1e-12, true, row_lse_keepdim_out);
            try expectArray(row_lse_keepdim_out, &.{ 2, 1 }, cosine_rows_keep.data);

            var distance_rows = try matrix.pairwiseDistance(other, 2, 1, false);
            defer distance_rows.deinit();
            try expectArray(distance_rows, &.{2}, &.{ 1, 3 });
            try matrix.pairwiseDistanceOut(other, 2, 1, false, row_lse_out);
            try expectArray(row_lse_out, &.{2}, distance_rows.data);

            var distance_rows_l1 = try matrix.pairwiseDistanceDim(other, 1, -1, true);
            defer distance_rows_l1.deinit();
            try expectArray(distance_rows_l1, &.{ 2, 1 }, &.{ 1, 3 });
            try matrix.pairwiseDistanceDimOut(other, 1, -1, true, row_lse_keepdim_out);
            try expectArray(row_lse_keepdim_out, &.{ 2, 1 }, distance_rows_l1.data);

            var bad_other = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 2 });
            defer bad_other.deinit();
            try std.testing.expectError(error.ShapeMismatch, matrix.cosineSimilarity(bad_other, 1, 1e-12, false));
            try std.testing.expectError(error.InvalidShape, matrix.cosineSimilarity(other, 1, -1e-12, false));
            try std.testing.expectError(error.InvalidShape, matrix.normalize(2, 1, -1e-12));

            try std.testing.expectError(error.InvalidShape, matrix.norm(0, null, false));
            try std.testing.expectError(error.InvalidAxis, matrix.logsumexp(2, false));
        }
    }.check;

    var matrix = try cooFromSlices(f64, gpa, 2, 3, &.{ 0, 1, 1 }, &.{ 0, 1, 2 }, &.{ 1, 2, 3 });
    defer matrix.deinit();
    try expectNorms(@TypeOf(matrix), matrix);
    var matrix_csr = try matrix.toCsr();
    defer matrix_csr.deinit();
    try expectNorms(@TypeOf(matrix_csr), matrix_csr);
    var matrix_csc = try matrix.toCsc();
    defer matrix_csc.deinit();
    try expectNorms(@TypeOf(matrix_csc), matrix_csc);
}

test "sparse dense weighted statistic helpers" {
    const gpa = std.testing.allocator;

    const expectWeightedStats = struct {
        fn expectArray(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            for (expected, values.data) |want, got| try std.testing.expectApproxEqAbs(want, got, 1e-12);
        }

        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var weights = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{
                1, 2, 1,
                3, 2, 1,
            }, &.{ 2, 3 });
            defer weights.deinit();

            var average_unweighted = try matrix.average(null, null, false);
            defer average_unweighted.deinit();
            try expectArray(average_unweighted, &.{}, &.{1});
            var scalar_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{});
            defer scalar_out.deinit();
            try matrix.averageOut(null, null, false, scalar_out);
            try expectArray(scalar_out, &.{}, average_unweighted.data);

            var average_weighted = try matrix.average(weights, null, false);
            defer average_weighted.deinit();
            try expectArray(average_weighted, &.{}, &.{8.0 / 10.0});
            try matrix.averageOut(weights, null, false, scalar_out);
            try expectArray(scalar_out, &.{}, average_weighted.data);

            var weighted_mean_flat = try matrix.weightedMean(weights, null, true);
            defer weighted_mean_flat.deinit();
            try expectArray(weighted_mean_flat, &.{ 1, 1 }, &.{8.0 / 10.0});
            var scalar_keepdim_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 1, 1 });
            defer scalar_keepdim_out.deinit();
            try matrix.weightedMeanOut(weights, null, true, scalar_keepdim_out);
            try expectArray(scalar_keepdim_out, &.{ 1, 1 }, weighted_mean_flat.data);

            var weighted_mean_rows = try matrix.weightedMean(weights, 1, false);
            defer weighted_mean_rows.deinit();
            try expectArray(weighted_mean_rows, &.{2}, &.{ 0.25, 7.0 / 6.0 });
            var row_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{2});
            defer row_out.deinit();
            try matrix.weightedMeanOut(weights, 1, false, row_out);
            try expectArray(row_out, &.{2}, weighted_mean_rows.data);

            var weighted_mean_rows_array = try matrix.weightedMeanArray(weights, 1, false);
            defer weighted_mean_rows_array.deinit();
            try expectArray(weighted_mean_rows_array, &.{2}, weighted_mean_rows.data);
            try matrix.weightedMeanArrayOut(weights, 1, false, row_out);
            try expectArray(row_out, &.{2}, weighted_mean_rows_array.data);

            var weighted_variance_flat = try matrix.weightedVariance(weights, null, false, 0);
            defer weighted_variance_flat.deinit();
            try expectArray(weighted_variance_flat, &.{}, &.{1.16});
            try matrix.weightedVarianceOut(weights, null, false, 0, scalar_out);
            try expectArray(scalar_out, &.{}, weighted_variance_flat.data);

            var weighted_variance_array_flat = try matrix.weightedVarianceArray(weights, null, false, 0);
            defer weighted_variance_array_flat.deinit();
            try expectArray(weighted_variance_array_flat, &.{}, weighted_variance_flat.data);
            try matrix.weightedVarianceArrayOut(weights, null, false, 0, scalar_out);
            try expectArray(scalar_out, &.{}, weighted_variance_array_flat.data);

            var weighted_var_rows = try matrix.weightedVar(weights, 1, false, 0);
            defer weighted_var_rows.deinit();
            try expectArray(weighted_var_rows, &.{2}, &.{ 3.0 / 16.0, 53.0 / 36.0 });
            try matrix.weightedVarOut(weights, 1, false, 0, row_out);
            try expectArray(row_out, &.{2}, weighted_var_rows.data);

            var weighted_var_rows_array = try matrix.weightedVarArray(weights, 1, false, 0);
            defer weighted_var_rows_array.deinit();
            try expectArray(weighted_var_rows_array, &.{2}, weighted_var_rows.data);
            try matrix.weightedVarArrayOut(weights, 1, false, 0, row_out);
            try expectArray(row_out, &.{2}, weighted_var_rows_array.data);

            var weighted_std_flat = try matrix.weightedStddev(weights, null, false, 0);
            defer weighted_std_flat.deinit();
            try expectArray(weighted_std_flat, &.{}, &.{@sqrt(1.16)});
            try matrix.weightedStddevOut(weights, null, false, 0, scalar_out);
            try expectArray(scalar_out, &.{}, weighted_std_flat.data);

            var weighted_stddev_array_flat = try matrix.weightedStddevArray(weights, null, false, 0);
            defer weighted_stddev_array_flat.deinit();
            try expectArray(weighted_stddev_array_flat, &.{}, weighted_std_flat.data);
            try matrix.weightedStddevArrayOut(weights, null, false, 0, scalar_out);
            try expectArray(scalar_out, &.{}, weighted_stddev_array_flat.data);

            var weighted_std_rows = try matrix.weightedStd(weights, 1, false, 0);
            defer weighted_std_rows.deinit();
            try expectArray(weighted_std_rows, &.{2}, &.{ @sqrt(3.0 / 16.0), @sqrt(53.0 / 36.0) });
            try matrix.weightedStdOut(weights, 1, false, 0, row_out);
            try expectArray(row_out, &.{2}, weighted_std_rows.data);

            var weighted_std_rows_array = try matrix.weightedStdArray(weights, 1, false, 0);
            defer weighted_std_rows_array.deinit();
            try expectArray(weighted_std_rows_array, &.{2}, weighted_std_rows.data);
            try matrix.weightedStdArrayOut(weights, 1, false, 0, row_out);
            try expectArray(row_out, &.{2}, weighted_std_rows_array.data);

            var weighted_quantile_flat = try matrix.weightedQuantile(weights, 0.5, null, false);
            defer weighted_quantile_flat.deinit();
            try expectArray(weighted_quantile_flat, &.{}, &.{0});
            try matrix.weightedQuantileOut(weights, 0.5, null, false, scalar_out);
            try expectArray(scalar_out, &.{}, weighted_quantile_flat.data);

            var weighted_quantile_array_flat = try matrix.weightedQuantileArray(weights, 0.5, null, false);
            defer weighted_quantile_array_flat.deinit();
            try expectArray(weighted_quantile_array_flat, &.{}, weighted_quantile_flat.data);
            try matrix.weightedQuantileArrayOut(weights, 0.5, null, false, scalar_out);
            try expectArray(scalar_out, &.{}, weighted_quantile_array_flat.data);

            var weighted_quantile_rows = try matrix.weightedQuantile(weights, 0.75, 1, false);
            defer weighted_quantile_rows.deinit();
            try expectArray(weighted_quantile_rows, &.{2}, &.{ 0, 2 });
            try matrix.weightedQuantileOut(weights, 0.75, 1, false, row_out);
            try expectArray(row_out, &.{2}, weighted_quantile_rows.data);

            var weighted_median_flat = try matrix.weightedMedian(weights, null, false);
            defer weighted_median_flat.deinit();
            try expectArray(weighted_median_flat, &.{}, weighted_quantile_flat.data);
            try matrix.weightedMedianOut(weights, null, false, scalar_out);
            try expectArray(scalar_out, &.{}, weighted_median_flat.data);

            var weighted_median_array_flat = try matrix.weightedMedianArray(weights, null, false);
            defer weighted_median_array_flat.deinit();
            try expectArray(weighted_median_array_flat, &.{}, weighted_median_flat.data);
            try matrix.weightedMedianArrayOut(weights, null, false, scalar_out);
            try expectArray(scalar_out, &.{}, weighted_median_array_flat.data);

            var weighted_median_rows = try matrix.weightedMedian(weights, 1, false);
            defer weighted_median_rows.deinit();
            try expectArray(weighted_median_rows, &.{2}, &.{ 0, 0 });
            try matrix.weightedMedianOut(weights, 1, false, row_out);
            try expectArray(row_out, &.{2}, weighted_median_rows.data);

            var bad_weights = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{ 1, 2 }, &.{2});
            defer bad_weights.deinit();
            try std.testing.expectError(error.ShapeMismatch, matrix.weightedMean(bad_weights, null, false));

            var negative_weights = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{
                1, -1, 1,
                1, 1,  1,
            }, &.{ 2, 3 });
            defer negative_weights.deinit();
            try std.testing.expectError(error.InvalidShape, matrix.weightedMean(negative_weights, null, false));
            try std.testing.expectError(error.InvalidShape, matrix.weightedQuantile(weights, 1.5, null, false));
        }
    }.check;

    var matrix = try cooFromSlices(f64, gpa, 2, 3, &.{ 0, 1, 1 }, &.{ 0, 1, 2 }, &.{ 1, 2, 3 });
    defer matrix.deinit();
    try expectWeightedStats(@TypeOf(matrix), matrix);
    var matrix_csr = try matrix.toCsr();
    defer matrix_csr.deinit();
    try expectWeightedStats(@TypeOf(matrix_csr), matrix_csr);
    var matrix_csc = try matrix.toCsc();
    defer matrix_csc.deinit();
    try expectWeightedStats(@TypeOf(matrix_csc), matrix_csc);
}

test "sparse dense covariance helpers" {
    const gpa = std.testing.allocator;

    const expectApproxArray = struct {
        fn check(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            for (expected, values.data) |want, got| try std.testing.expectApproxEqAbs(want, got, 1e-12);
        }
    }.check;

    const expectCovariance = struct {
        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var covariance = try matrix.cov(false, 1);
            defer covariance.deinit();
            try expectApproxArray(covariance, &.{ 2, 2 }, &.{ 1, 2, 2, 4 });
            var cov_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 2 });
            defer cov_out.deinit();
            try matrix.covOut(false, 1, cov_out);
            try expectApproxArray(cov_out, &.{ 2, 2 }, covariance.data);

            var corr = try matrix.corrcoef(false);
            defer corr.deinit();
            try expectApproxArray(corr, &.{ 2, 2 }, &.{ 1, 1, 1, 1 });
            try matrix.corrcoefOut(false, cov_out);
            try expectApproxArray(cov_out, &.{ 2, 2 }, corr.data);

            var weights = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{ 1, 2, 1 }, &.{3});
            defer weights.deinit();
            var weighted_covariance = try matrix.weightedCov(weights, false, 1);
            defer weighted_covariance.deinit();
            try expectApproxArray(weighted_covariance, &.{ 2, 2 }, &.{ 2.0 / 3.0, 4.0 / 3.0, 4.0 / 3.0, 8.0 / 3.0 });
            try matrix.weightedCovOut(weights, false, 1, cov_out);
            try expectApproxArray(cov_out, &.{ 2, 2 }, weighted_covariance.data);

            var weighted_corr = try matrix.weightedCorrcoef(weights, false);
            defer weighted_corr.deinit();
            try expectApproxArray(weighted_corr, &.{ 2, 2 }, &.{ 1, 1, 1, 1 });
            try matrix.weightedCorrcoefOut(weights, false, cov_out);
            try expectApproxArray(cov_out, &.{ 2, 2 }, weighted_corr.data);

            var bad_weights = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{ 1, 2 }, &.{2});
            defer bad_weights.deinit();
            try std.testing.expectError(error.ShapeMismatch, matrix.weightedCov(bad_weights, false, 1));
            try std.testing.expectError(error.InvalidShape, matrix.cov(false, 3));
        }
    }.check;

    var observations = try cooFromSlices(f64, gpa, 3, 2, &.{ 0, 0, 1, 1, 2, 2 }, &.{ 0, 1, 0, 1, 0, 1 }, &.{ 1, 2, 2, 4, 3, 6 });
    defer observations.deinit();
    try expectCovariance(@TypeOf(observations), observations);
    var observations_csr = try observations.toCsr();
    defer observations_csr.deinit();
    try expectCovariance(@TypeOf(observations_csr), observations_csr);
    var observations_csc = try observations.toCsc();
    defer observations_csc.deinit();
    try expectCovariance(@TypeOf(observations_csc), observations_csc);

    const expectNanCovariance = struct {
        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var nan_covariance = try matrix.nanCov(false, 1);
            defer nan_covariance.deinit();
            try expectApproxArray(nan_covariance, &.{ 2, 2 }, &.{ 2, 4, 4, 8 });
            var cov_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 2 });
            defer cov_out.deinit();
            try matrix.nanCovOut(false, 1, cov_out);
            try expectApproxArray(cov_out, &.{ 2, 2 }, nan_covariance.data);

            var nan_corr = try matrix.nanCorrcoef(false);
            defer nan_corr.deinit();
            try expectApproxArray(nan_corr, &.{ 2, 2 }, &.{ 1, 1, 1, 1 });
            try matrix.nanCorrcoefOut(false, cov_out);
            try expectApproxArray(cov_out, &.{ 2, 2 }, nan_corr.data);
        }
    }.check;

    const nan = std.math.nan(f64);
    var nan_observations = try cooFromSlices(f64, gpa, 3, 2, &.{ 0, 0, 1, 1, 2, 2 }, &.{ 0, 1, 0, 1, 0, 1 }, &.{ 1, 2, nan, nan, 3, 6 });
    defer nan_observations.deinit();
    try expectNanCovariance(@TypeOf(nan_observations), nan_observations);
    var nan_observations_csr = try nan_observations.toCsr();
    defer nan_observations_csr.deinit();
    try expectNanCovariance(@TypeOf(nan_observations_csr), nan_observations_csr);
    var nan_observations_csc = try nan_observations.toCsc();
    defer nan_observations_csc.deinit();
    try expectNanCovariance(@TypeOf(nan_observations_csc), nan_observations_csc);

    var rowvar_matrix = try cooFromSlices(f64, gpa, 2, 3, &.{ 0, 0, 0, 1, 1, 1 }, &.{ 0, 1, 2, 0, 1, 2 }, &.{ 1, 2, 3, 2, 4, 6 });
    defer rowvar_matrix.deinit();
    var row_covariance = try rowvar_matrix.cov(true, 1);
    defer row_covariance.deinit();
    try expectApproxArray(row_covariance, &.{ 2, 2 }, &.{ 1, 2, 2, 4 });
}

test "sparse dense nan cleanup helpers" {
    const gpa = std.testing.allocator;

    const expectCleanup = struct {
        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var cleaned = try matrix.nanToNum(9, 7, -7);
            defer cleaned.deinit();
            try std.testing.expectEqualSlices(usize, &.{ 2, 3 }, cleaned.shape);
            try std.testing.expectEqualSlices(f64, &.{ 9, 0, 7, -7, 5, 0 }, cleaned.data);
            var cleaned_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer cleaned_out.deinit();
            try matrix.nanToNumOut(9, 7, -7, cleaned_out);
            try std.testing.expectEqualSlices(f64, cleaned.data, cleaned_out.data);

            var default_cleaned = try matrix.nanToNumDefault();
            defer default_cleaned.deinit();
            try std.testing.expectEqualSlices(usize, cleaned.shape, default_cleaned.shape);
            try std.testing.expectEqual(@as(f64, 0), default_cleaned.data[0]);
            try std.testing.expectEqual(std.math.floatMax(f64), default_cleaned.data[2]);
            try std.testing.expectEqual(-std.math.floatMax(f64), default_cleaned.data[3]);
            try matrix.nanToNumDefaultOut(cleaned_out);
            try std.testing.expectEqualSlices(f64, default_cleaned.data, cleaned_out.data);
        }
    }.check;

    var special = try cooFromSlices(
        f64,
        gpa,
        2,
        3,
        &.{ 0, 0, 1, 1 },
        &.{ 0, 2, 0, 1 },
        &.{ std.math.nan(f64), std.math.inf(f64), -std.math.inf(f64), 5 },
    );
    defer special.deinit();
    try expectCleanup(@TypeOf(special), special);
    var special_csr = try special.toCsr();
    defer special_csr.deinit();
    try expectCleanup(@TypeOf(special_csr), special_csr);
    var special_csc = try special.toCsc();
    defer special_csc.deinit();
    try expectCleanup(@TypeOf(special_csc), special_csc);

    const expectNanReductions = struct {
        fn expectArray(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            for (expected, values.data) |want, got| try std.testing.expectApproxEqAbs(want, got, 1e-12);
        }

        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var scalar_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{});
            defer scalar_out.deinit();
            var vector_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{3});
            defer vector_out.deinit();
            var keepdim_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 1, 1 });
            defer keepdim_out.deinit();

            var flat_sum = try matrix.nansum(null, false);
            defer flat_sum.deinit();
            try expectArray(flat_sum, &.{}, &.{24});
            try matrix.nansumOut(null, false, scalar_out);
            try expectArray(scalar_out, &.{}, flat_sum.data);

            var all_sum_keepdim = try matrix.nansumAxes(&.{ 0, 1 }, true);
            defer all_sum_keepdim.deinit();
            try expectArray(all_sum_keepdim, &.{ 1, 1 }, flat_sum.data);
            try matrix.nansumAxesOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_sum_keepdim.data);

            var column_sum = try matrix.nansumDim(0, false);
            defer column_sum.deinit();
            try expectArray(column_sum, &.{3}, &.{ 8, 13, 3 });
            try matrix.nansumDimOut(0, false, vector_out);
            try expectArray(vector_out, &.{3}, column_sum.data);

            var all_sum_dims = try matrix.nansumDims(&.{ 0, 1 }, false);
            defer all_sum_dims.deinit();
            try expectArray(all_sum_dims, &.{}, flat_sum.data);
            try matrix.nansumDimsOut(&.{ 0, 1 }, false, scalar_out);
            try expectArray(scalar_out, &.{}, all_sum_dims.data);

            var row_mean = try matrix.nanmean(1, false);
            defer row_mean.deinit();
            try expectArray(row_mean, &.{3}, &.{ 2, 2.5, 5 });
            try matrix.nanmeanOut(1, false, vector_out);
            try expectArray(vector_out, &.{3}, row_mean.data);

            var column_mean = try matrix.nanmeanDim(0, false);
            defer column_mean.deinit();
            try expectArray(column_mean, &.{3}, &.{ 8.0 / 3.0, 6.5, 1.5 });
            try matrix.nanmeanDimOut(0, false, vector_out);
            try expectArray(vector_out, &.{3}, column_mean.data);

            var all_mean_keepdim = try matrix.nanmeanAxes(&.{ 0, 1 }, true);
            defer all_mean_keepdim.deinit();
            try expectArray(all_mean_keepdim, &.{ 1, 1 }, &.{24.0 / 7.0});
            try matrix.nanmeanAxesOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_mean_keepdim.data);

            var all_mean_dims = try matrix.nanmeanDims(&.{ 0, 1 }, false);
            defer all_mean_dims.deinit();
            try expectArray(all_mean_dims, &.{}, all_mean_keepdim.data);
            try matrix.nanmeanDimsOut(&.{ 0, 1 }, false, scalar_out);
            try expectArray(scalar_out, &.{}, all_mean_dims.data);

            var row_var = try matrix.nanvar(1, false, 0);
            defer row_var.deinit();
            try expectArray(row_var, &.{3}, &.{ 1, 6.25, 38.0 / 3.0 });
            try matrix.nanvarOut(1, false, 0, vector_out);
            try expectArray(vector_out, &.{3}, row_var.data);

            var column_var = try matrix.nanvarDim(0, false, 0);
            defer column_var.deinit();
            try expectArray(column_var, &.{3}, &.{ 86.0 / 9.0, 2.25, 2.25 });
            try matrix.nanvarDimOut(0, false, 0, vector_out);
            try expectArray(vector_out, &.{3}, column_var.data);

            var all_var_keepdim = try matrix.nanvarAxes(&.{ 0, 1 }, true, 0);
            defer all_var_keepdim.deinit();
            try expectArray(all_var_keepdim, &.{ 1, 1 }, &.{460.0 / 49.0});
            try matrix.nanvarAxesOut(&.{ 0, 1 }, true, 0, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_var_keepdim.data);

            var all_var_dims = try matrix.nanvarDims(&.{ 0, 1 }, false, 0);
            defer all_var_dims.deinit();
            try expectArray(all_var_dims, &.{}, all_var_keepdim.data);
            try matrix.nanvarDimsOut(&.{ 0, 1 }, false, 0, scalar_out);
            try expectArray(scalar_out, &.{}, all_var_dims.data);

            var row_std = try matrix.nanstd(1, false, 0);
            defer row_std.deinit();
            try expectArray(row_std, &.{3}, &.{ 1, 2.5, @sqrt(38.0 / 3.0) });
            try matrix.nanstdOut(1, false, 0, vector_out);
            try expectArray(vector_out, &.{3}, row_std.data);

            var column_std = try matrix.nanstdDim(0, false, 0);
            defer column_std.deinit();
            try expectArray(column_std, &.{3}, &.{ @sqrt(86.0 / 9.0), 1.5, 1.5 });
            try matrix.nanstdDimOut(0, false, 0, vector_out);
            try expectArray(vector_out, &.{3}, column_std.data);

            var all_std_keepdim = try matrix.nanstdAxes(&.{ 0, 1 }, true, 0);
            defer all_std_keepdim.deinit();
            try expectArray(all_std_keepdim, &.{ 1, 1 }, &.{@sqrt(460.0 / 49.0)});
            try matrix.nanstdAxesOut(&.{ 0, 1 }, true, 0, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_std_keepdim.data);

            var all_std_dims = try matrix.nanstdDims(&.{ 0, 1 }, false, 0);
            defer all_std_dims.deinit();
            try expectArray(all_std_dims, &.{}, all_std_keepdim.data);
            try matrix.nanstdDimsOut(&.{ 0, 1 }, false, 0, scalar_out);
            try expectArray(scalar_out, &.{}, all_std_dims.data);

            var row_median = try matrix.nanmedian(1, false);
            defer row_median.deinit();
            try expectArray(row_median, &.{3}, &.{ 2, 2.5, 7 });
            try matrix.nanmedianOut(1, false, vector_out);
            try expectArray(vector_out, &.{3}, row_median.data);

            var column_median = try matrix.nanmedianDim(0, false);
            defer column_median.deinit();
            try expectArray(column_median, &.{3}, &.{ 1, 6.5, 1.5 });
            try matrix.nanmedianDimOut(0, false, vector_out);
            try expectArray(vector_out, &.{3}, column_median.data);

            var all_median_keepdim = try matrix.nanmedianAxes(&.{ 0, 1 }, true);
            defer all_median_keepdim.deinit();
            try expectArray(all_median_keepdim, &.{ 1, 1 }, &.{3});
            try matrix.nanmedianAxesOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_median_keepdim.data);

            var all_median_dims = try matrix.nanmedianDims(&.{ 0, 1 }, false);
            defer all_median_dims.deinit();
            try expectArray(all_median_dims, &.{}, all_median_keepdim.data);
            try matrix.nanmedianDimsOut(&.{ 0, 1 }, false, scalar_out);
            try expectArray(scalar_out, &.{}, all_median_dims.data);

            var row_quantile = try matrix.nanquantile(0.25, 1, false);
            defer row_quantile.deinit();
            try expectArray(row_quantile, &.{3}, &.{ 1.5, 1.25, 3.5 });
            try matrix.nanquantileOut(0.25, 1, false, vector_out);
            try expectArray(vector_out, &.{3}, row_quantile.data);

            var column_quantile = try matrix.nanquantileDim(0.25, 0, false);
            defer column_quantile.deinit();
            try expectArray(column_quantile, &.{3}, &.{ 0.5, 5.75, 0.75 });
            try matrix.nanquantileDimOut(0.25, 0, false, vector_out);
            try expectArray(vector_out, &.{3}, column_quantile.data);

            var all_quantile_keepdim = try matrix.nanquantileAxes(0.25, &.{ 0, 1 }, true);
            defer all_quantile_keepdim.deinit();
            try expectArray(all_quantile_keepdim, &.{ 1, 1 }, &.{0.5});
            try matrix.nanquantileAxesOut(0.25, &.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_quantile_keepdim.data);

            var all_quantile_dims = try matrix.nanquantileDims(0.25, &.{ 0, 1 }, false);
            defer all_quantile_dims.deinit();
            try expectArray(all_quantile_dims, &.{}, all_quantile_keepdim.data);
            try matrix.nanquantileDimsOut(0.25, &.{ 0, 1 }, false, scalar_out);
            try expectArray(scalar_out, &.{}, all_quantile_dims.data);

            var row_percentile = try matrix.nanpercentile(75, 1, false);
            defer row_percentile.deinit();
            try expectArray(row_percentile, &.{3}, &.{ 2.5, 3.75, 7.5 });
            try matrix.nanpercentileOut(75, 1, false, vector_out);
            try expectArray(vector_out, &.{3}, row_percentile.data);

            var column_percentile = try matrix.nanpercentileDim(75, 0, false);
            defer column_percentile.deinit();
            try expectArray(column_percentile, &.{3}, &.{ 4, 7.25, 2.25 });
            try matrix.nanpercentileDimOut(75, 0, false, vector_out);
            try expectArray(vector_out, &.{3}, column_percentile.data);

            var all_percentile_keepdim = try matrix.nanpercentileAxes(75, &.{ 0, 1 }, true);
            defer all_percentile_keepdim.deinit();
            try expectArray(all_percentile_keepdim, &.{ 1, 1 }, &.{6});
            try matrix.nanpercentileAxesOut(75, &.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_percentile_keepdim.data);

            var all_percentile_dims = try matrix.nanpercentileDims(75, &.{ 0, 1 }, false);
            defer all_percentile_dims.deinit();
            try expectArray(all_percentile_dims, &.{}, all_percentile_keepdim.data);
            try matrix.nanpercentileDimsOut(75, &.{ 0, 1 }, false, scalar_out);
            try expectArray(scalar_out, &.{}, all_percentile_dims.data);

            var row_min = try matrix.nanmin(1, false);
            defer row_min.deinit();
            try expectArray(row_min, &.{3}, &.{ 1, 0, 0 });
            try matrix.nanminOut(1, false, vector_out);
            try expectArray(vector_out, &.{3}, row_min.data);

            var column_min = try matrix.nanminDim(0, false);
            defer column_min.deinit();
            try expectArray(column_min, &.{3}, &.{ 0, 5, 0 });
            try matrix.nanminDimOut(0, false, vector_out);
            try expectArray(vector_out, &.{3}, column_min.data);

            var all_min = try matrix.nanminAxes(&.{ 0, 1 }, false);
            defer all_min.deinit();
            try expectArray(all_min, &.{}, &.{0});
            try matrix.nanminAxesOut(&.{ 0, 1 }, false, scalar_out);
            try expectArray(scalar_out, &.{}, all_min.data);

            var all_min_dims = try matrix.nanminDims(&.{ 0, 1 }, true);
            defer all_min_dims.deinit();
            try expectArray(all_min_dims, &.{ 1, 1 }, all_min.data);
            try matrix.nanminDimsOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_min_dims.data);

            var row_max = try matrix.nanmax(1, false);
            defer row_max.deinit();
            try expectArray(row_max, &.{3}, &.{ 3, 5, 8 });
            try matrix.nanmaxOut(1, false, vector_out);
            try expectArray(vector_out, &.{3}, row_max.data);

            var column_max = try matrix.nanmaxDim(0, false);
            defer column_max.deinit();
            try expectArray(column_max, &.{3}, &.{ 7, 8, 3 });
            try matrix.nanmaxDimOut(0, false, vector_out);
            try expectArray(vector_out, &.{3}, column_max.data);

            var all_max = try matrix.nanmaxAxes(&.{ 0, 1 }, false);
            defer all_max.deinit();
            try expectArray(all_max, &.{}, &.{8});
            try matrix.nanmaxAxesOut(&.{ 0, 1 }, false, scalar_out);
            try expectArray(scalar_out, &.{}, all_max.data);

            var all_max_dims = try matrix.nanmaxDims(&.{ 0, 1 }, true);
            defer all_max_dims.deinit();
            try expectArray(all_max_dims, &.{ 1, 1 }, all_max.data);
            try matrix.nanmaxDimsOut(&.{ 0, 1 }, true, keepdim_out);
            try expectArray(keepdim_out, &.{ 1, 1 }, all_max_dims.data);

            try std.testing.expectError(error.InvalidAxis, matrix.nansum(2, false));
            try std.testing.expectError(error.InvalidAxis, matrix.nanvar(2, false, 0));
            try std.testing.expectError(error.InvalidAxis, matrix.nanquantile(0.5, 2, false));
            try std.testing.expectError(error.InvalidShape, matrix.nanquantile(-0.1, null, false));
        }
    }.check;

    var values = try cooFromSlices(
        f64,
        gpa,
        3,
        3,
        &.{ 0, 0, 0, 1, 1, 2, 2 },
        &.{ 0, 1, 2, 1, 2, 0, 1 },
        &.{ 1, std.math.nan(f64), 3, 5, std.math.nan(f64), 7, 8 },
    );
    defer values.deinit();
    try expectNanReductions(@TypeOf(values), values);
    var values_csr = try values.toCsr();
    defer values_csr.deinit();
    try expectNanReductions(@TypeOf(values_csr), values_csr);
    var values_csc = try values.toCsc();
    defer values_csc.deinit();
    try expectNanReductions(@TypeOf(values_csc), values_csc);
}

test "sparse dense cumulative helpers" {
    const gpa = std.testing.allocator;

    const expectCumulative = struct {
        fn expectArray(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            try std.testing.expectEqualSlices(f64, expected, values.data);
        }

        fn expectApproxArray(values: array_mod.Array(f64), shape: []const usize, expected: []const f64) !void {
            try std.testing.expectEqualSlices(usize, shape, values.shape);
            for (expected, values.data) |want, got| try std.testing.expectApproxEqAbs(want, got, 1e-12);
        }

        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var flat_sum = try matrix.cumsum();
            defer flat_sum.deinit();
            try expectArray(flat_sum, &.{ 2, 3 }, &.{ 1, 1, 1, 1, 3, 6 });
            var cumulative_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 3 });
            defer cumulative_out.deinit();
            try matrix.cumsumOut(cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, flat_sum.data);

            var row_sum = try matrix.cumsumAxis(1);
            defer row_sum.deinit();
            try expectArray(row_sum, &.{ 2, 3 }, &.{ 1, 1, 1, 0, 2, 5 });
            try matrix.cumsumAxisOut(1, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, row_sum.data);

            var column_sum = try matrix.cumsumDim(0);
            defer column_sum.deinit();
            try expectArray(column_sum, &.{ 2, 3 }, &.{ 1, 0, 0, 1, 2, 3 });
            try matrix.cumsumDimOut(0, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, column_sum.data);

            var flat_product = try matrix.cumprod();
            defer flat_product.deinit();
            try expectArray(flat_product, &.{ 2, 3 }, &.{ 1, 0, 0, 0, 0, 0 });
            try matrix.cumprodOut(cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, flat_product.data);

            var row_product = try matrix.cumprodAxis(1);
            defer row_product.deinit();
            try expectArray(row_product, &.{ 2, 3 }, &.{ 1, 0, 0, 0, 0, 0 });
            try matrix.cumprodAxisOut(1, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, row_product.data);

            var column_product = try matrix.cumprodDim(0);
            defer column_product.deinit();
            try expectArray(column_product, &.{ 2, 3 }, &.{ 1, 0, 0, 0, 0, 0 });
            try matrix.cumprodDimOut(0, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, column_product.data);

            var flat_max = try matrix.cummax();
            defer flat_max.deinit();
            try expectArray(flat_max, &.{ 2, 3 }, &.{ 1, 1, 1, 1, 2, 3 });
            try matrix.cummaxOut(cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, flat_max.data);

            var row_max = try matrix.cummaxAxis(1);
            defer row_max.deinit();
            try expectArray(row_max, &.{ 2, 3 }, &.{ 1, 1, 1, 0, 2, 3 });
            try matrix.cummaxAxisOut(1, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, row_max.data);

            var column_max = try matrix.cummaxDim(0);
            defer column_max.deinit();
            try expectArray(column_max, &.{ 2, 3 }, &.{ 1, 0, 0, 1, 2, 3 });
            try matrix.cummaxDimOut(0, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, column_max.data);

            var flat_min = try matrix.cummin();
            defer flat_min.deinit();
            try expectArray(flat_min, &.{ 2, 3 }, &.{ 1, 0, 0, 0, 0, 0 });
            try matrix.cumminOut(cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, flat_min.data);

            var row_min = try matrix.cumminAxis(1);
            defer row_min.deinit();
            try expectArray(row_min, &.{ 2, 3 }, &.{ 1, 0, 0, 0, 0, 0 });
            try matrix.cumminAxisOut(1, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, row_min.data);

            var column_min = try matrix.cumminDim(0);
            defer column_min.deinit();
            try expectArray(column_min, &.{ 2, 3 }, &.{ 1, 0, 0, 0, 0, 0 });
            try matrix.cumminDimOut(0, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, column_min.data);

            const log_e_plus_one = std.math.log(f64, std.math.e, std.math.exp(@as(f64, 1)) + 1);
            const log_e_plus_two = std.math.log(f64, std.math.e, std.math.exp(@as(f64, 1)) + 2);
            var log_rows = try matrix.logcumsumexpAxis(1);
            defer log_rows.deinit();
            try expectApproxArray(log_rows, &.{ 2, 3 }, &.{
                1,
                log_e_plus_one,
                log_e_plus_two,
                0,
                std.math.log(f64, std.math.e, 1 + std.math.exp(@as(f64, 2))),
                std.math.log(f64, std.math.e, 1 + std.math.exp(@as(f64, 2)) + std.math.exp(@as(f64, 3))),
            });
            try matrix.logcumsumexpAxisOut(1, cumulative_out);
            try expectApproxArray(cumulative_out, &.{ 2, 3 }, log_rows.data);

            var log_flat = try matrix.logcumsumexp();
            defer log_flat.deinit();
            try std.testing.expectApproxEqAbs(@as(f64, 1), log_flat.data[0], 1e-12);
            try std.testing.expectApproxEqAbs(log_e_plus_one, log_flat.data[1], 1e-12);
            try matrix.logcumsumexpOut(cumulative_out);
            try expectApproxArray(cumulative_out, &.{ 2, 3 }, log_flat.data);

            var log_columns = try matrix.logcumsumexpDim(0);
            defer log_columns.deinit();
            try std.testing.expectApproxEqAbs(@as(f64, 1), log_columns.data[0], 1e-12);
            try std.testing.expectApproxEqAbs(log_e_plus_one, log_columns.data[3], 1e-12);
            try matrix.logcumsumexpDimOut(0, cumulative_out);
            try expectApproxArray(cumulative_out, &.{ 2, 3 }, log_columns.data);

            var diff_rows = try matrix.diff(1, 1);
            defer diff_rows.deinit();
            try expectArray(diff_rows, &.{ 2, 2 }, &.{ -1, 0, 2, 1 });
            var diff_rows_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 2 });
            defer diff_rows_out.deinit();
            try matrix.diffOut(1, 1, diff_rows_out);
            try expectArray(diff_rows_out, &.{ 2, 2 }, diff_rows.data);

            var diff_columns = try matrix.diff(0, 1);
            defer diff_columns.deinit();
            try expectArray(diff_columns, &.{ 1, 3 }, &.{ -1, 2, 3 });
            var diff_columns_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 1, 3 });
            defer diff_columns_out.deinit();
            try matrix.diffOut(0, 1, diff_columns_out);
            try expectArray(diff_columns_out, &.{ 1, 3 }, diff_columns.data);

            var diff_rows_twice = try matrix.diff(1, 2);
            defer diff_rows_twice.deinit();
            try expectArray(diff_rows_twice, &.{ 2, 1 }, &.{ 1, -1 });
            var diff_rows_twice_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 1 });
            defer diff_rows_twice_out.deinit();
            try matrix.diffOut(1, 2, diff_rows_twice_out);
            try expectArray(diff_rows_twice_out, &.{ 2, 1 }, diff_rows_twice.data);

            var diff_zero = try matrix.diff(1, 0);
            defer diff_zero.deinit();
            try expectArray(diff_zero, &.{ 2, 3 }, &.{ 1, 0, 0, 0, 2, 3 });
            try matrix.diffOut(1, 0, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, diff_zero.data);

            var prepend = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{ -1, -2 }, &.{ 2, 1 });
            defer prepend.deinit();
            var append = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{ 4, 5 }, &.{ 2, 1 });
            defer append.deinit();
            var diff_with = try matrix.diffWith(1, 1, prepend, append);
            defer diff_with.deinit();
            try expectArray(diff_with, &.{ 2, 4 }, &.{ 2, -1, 0, 4, 2, 2, 1, 2 });
            var diff_with_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{ 2, 4 });
            defer diff_with_out.deinit();
            try matrix.diffWithOut(1, 1, prepend, append, diff_with_out);
            try expectArray(diff_with_out, &.{ 2, 4 }, diff_with.data);

            var ediff_prepend = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{-9}, &.{1});
            defer ediff_prepend.deinit();
            var ediff_append = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{ 9, 10 }, &.{2});
            defer ediff_append.deinit();
            var edge_diff = try matrix.ediff1d(ediff_prepend, ediff_append);
            defer edge_diff.deinit();
            try expectArray(edge_diff, &.{8}, &.{ -9, -1, 0, 0, 2, 1, 9, 10 });
            var edge_diff_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{8});
            defer edge_diff_out.deinit();
            try matrix.ediff1dOut(ediff_prepend, ediff_append, edge_diff_out);
            try expectArray(edge_diff_out, &.{8}, edge_diff.data);

            var trap_rows = try matrix.trapezoid(null, 1, 1);
            defer trap_rows.deinit();
            try expectArray(trap_rows, &.{2}, &.{ 0.5, 3.5 });
            var trap_rows_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{2});
            defer trap_rows_out.deinit();
            try matrix.trapezoidOut(null, 1, 1, trap_rows_out);
            try expectArray(trap_rows_out, &.{2}, trap_rows.data);

            var x_values = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{ 0, 1, 3 }, &.{3});
            defer x_values.deinit();
            var trap_rows_x = try matrix.trapezoid(x_values, 1, 1);
            defer trap_rows_x.deinit();
            try expectArray(trap_rows_x, &.{2}, &.{ 0.5, 6 });
            try matrix.trapezoidOut(x_values, 1, 1, trap_rows_out);
            try expectArray(trap_rows_out, &.{2}, trap_rows_x.data);

            var trap_columns = try matrix.trapz(null, 2, 0);
            defer trap_columns.deinit();
            try expectArray(trap_columns, &.{3}, &.{ 1, 2, 3 });
            var trap_columns_out = try array_mod.Array(f64).zeros(matrix.allocator, &.{3});
            defer trap_columns_out.deinit();
            try matrix.trapzOut(null, 2, 0, trap_columns_out);
            try expectArray(trap_columns_out, &.{3}, trap_columns.data);

            var grad_rows = try matrix.gradient(null, 1, 1);
            defer grad_rows.deinit();
            try expectArray(grad_rows, &.{ 2, 3 }, &.{ -1, -0.5, 0, 2, 1.5, 1 });
            try matrix.gradientOut(null, 1, 1, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, grad_rows.data);

            var grad_columns = try matrix.gradient(null, 2, 0);
            defer grad_columns.deinit();
            try expectArray(grad_columns, &.{ 2, 3 }, &.{ -0.5, 1, 1.5, -0.5, 1, 1.5 });
            try matrix.gradientOut(null, 2, 0, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, grad_columns.data);

            var grad_rows_x = try matrix.gradient(x_values, 1, 1);
            defer grad_rows_x.deinit();
            try expectArray(grad_rows_x, &.{ 2, 3 }, &.{ -1, -1.0 / 3.0, 0, 2, 1, 0.5 });
            try matrix.gradientOut(x_values, 1, 1, cumulative_out);
            try expectArray(cumulative_out, &.{ 2, 3 }, grad_rows_x.data);

            var bad_x_values = try array_mod.Array(f64).fromSlice(matrix.allocator, &.{ 0, 1 }, &.{2});
            defer bad_x_values.deinit();
            try std.testing.expectError(error.ShapeMismatch, matrix.trapezoid(bad_x_values, 1, 1));
            try std.testing.expectError(error.ShapeMismatch, matrix.gradient(bad_x_values, 1, 1));

            try std.testing.expectError(error.InvalidAxis, matrix.cumsumAxis(2));
            try std.testing.expectError(error.InvalidAxis, matrix.logcumsumexpAxis(2));
            try std.testing.expectError(error.InvalidAxis, matrix.diff(2, 1));
        }
    }.check;

    var matrix = try cooFromSlices(f64, gpa, 2, 3, &.{ 0, 1, 1 }, &.{ 0, 1, 2 }, &.{ 1, 2, 3 });
    defer matrix.deinit();
    try expectCumulative(@TypeOf(matrix), matrix);
    var matrix_csr = try matrix.toCsr();
    defer matrix_csr.deinit();
    try expectCumulative(@TypeOf(matrix_csr), matrix_csr);
    var matrix_csc = try matrix.toCsc();
    defer matrix_csc.deinit();
    try expectCumulative(@TypeOf(matrix_csc), matrix_csc);
}

test "sparse stored rounding unary helpers preserve structure" {
    const gpa = std.testing.allocator;
    var coo = try cooFromSlices(f64, gpa, 2, 2, &.{ 0, 0, 1 }, &.{ 0, 1, 1 }, &.{ -1.7, 2.2, 3.8 });
    defer coo.deinit();

    var coo_floor = try coo.floor();
    defer coo_floor.deinit();
    try std.testing.expectEqualSlices(usize, coo.row_indices, coo_floor.row_indices);
    try std.testing.expectEqualSlices(usize, coo.col_indices, coo_floor.col_indices);
    try std.testing.expectEqualSlices(f64, &.{ -2, 2, 3 }, coo_floor.values);
    var coo_ceil = try coo.ceil();
    defer coo_ceil.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1, 3, 4 }, coo_ceil.values);
    var coo_round = try coo.round();
    defer coo_round.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -2, 2, 4 }, coo_round.values);
    var coo_trunc = try coo.trunc();
    defer coo_trunc.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1, 2, 3 }, coo_trunc.values);
    var coo_clip_min = try coo.clipMin(0);
    defer coo_clip_min.deinit();
    try std.testing.expectEqualSlices(usize, coo.row_indices, coo_clip_min.row_indices);
    try std.testing.expectEqualSlices(usize, coo.col_indices, coo_clip_min.col_indices);
    try std.testing.expectEqualSlices(f64, &.{ 0, 2.2, 3.8 }, coo_clip_min.values);
    var coo_max_scalar = try coo.maximumScalar(0);
    defer coo_max_scalar.deinit();
    try std.testing.expectEqualSlices(f64, coo_clip_min.values, coo_max_scalar.values);
    var coo_clip_max = try coo.clipMax(3);
    defer coo_clip_max.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1.7, 2.2, 3 }, coo_clip_max.values);
    var coo_min_scalar = try coo.minimumScalar(3);
    defer coo_min_scalar.deinit();
    try std.testing.expectEqualSlices(f64, coo_clip_max.values, coo_min_scalar.values);
    var coo_clip = try coo.clip(-1, 3);
    defer coo_clip.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1, 2.2, 3 }, coo_clip.values);
    try std.testing.expectError(error.InvalidShape, coo.clip(3, -1));

    var csr = try coo.toCsr();
    defer csr.deinit();
    var csr_floor = try csr.floor();
    defer csr_floor.deinit();
    try std.testing.expectEqualSlices(usize, csr.row_offsets, csr_floor.row_offsets);
    try std.testing.expectEqualSlices(usize, csr.col_indices, csr_floor.col_indices);
    try std.testing.expectEqualSlices(f64, &.{ -2, 2, 3 }, csr_floor.values);
    var csr_ceil = try csr.ceil();
    defer csr_ceil.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1, 3, 4 }, csr_ceil.values);
    var csr_round = try csr.round();
    defer csr_round.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -2, 2, 4 }, csr_round.values);
    var csr_trunc = try csr.trunc();
    defer csr_trunc.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1, 2, 3 }, csr_trunc.values);
    var csr_clip_min = try csr.clampMin(0);
    defer csr_clip_min.deinit();
    try std.testing.expectEqualSlices(usize, csr.row_offsets, csr_clip_min.row_offsets);
    try std.testing.expectEqualSlices(usize, csr.col_indices, csr_clip_min.col_indices);
    try std.testing.expectEqualSlices(f64, &.{ 0, 2.2, 3.8 }, csr_clip_min.values);
    var csr_max_scalar = try csr.maxScalar(0);
    defer csr_max_scalar.deinit();
    try std.testing.expectEqualSlices(f64, csr_clip_min.values, csr_max_scalar.values);
    var csr_clip_max = try csr.clampMax(3);
    defer csr_clip_max.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1.7, 2.2, 3 }, csr_clip_max.values);
    var csr_min_scalar = try csr.minScalar(3);
    defer csr_min_scalar.deinit();
    try std.testing.expectEqualSlices(f64, csr_clip_max.values, csr_min_scalar.values);
    var csr_clip = try csr.clamp(-1, 3);
    defer csr_clip.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1, 2.2, 3 }, csr_clip.values);
    try std.testing.expectError(error.InvalidShape, csr.clamp(3, -1));

    var csc = try coo.toCsc();
    defer csc.deinit();
    var csc_floor = try csc.floor();
    defer csc_floor.deinit();
    try std.testing.expectEqualSlices(usize, csc.col_offsets, csc_floor.col_offsets);
    try std.testing.expectEqualSlices(usize, csc.row_indices, csc_floor.row_indices);
    try std.testing.expectEqualSlices(f64, &.{ -2, 2, 3 }, csc_floor.values);
    var csc_ceil = try csc.ceil();
    defer csc_ceil.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1, 3, 4 }, csc_ceil.values);
    var csc_round = try csc.round();
    defer csc_round.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -2, 2, 4 }, csc_round.values);
    var csc_trunc = try csc.trunc();
    defer csc_trunc.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1, 2, 3 }, csc_trunc.values);
    var csc_clip_min = try csc.clipMin(0);
    defer csc_clip_min.deinit();
    try std.testing.expectEqualSlices(usize, csc.col_offsets, csc_clip_min.col_offsets);
    try std.testing.expectEqualSlices(usize, csc.row_indices, csc_clip_min.row_indices);
    try std.testing.expectEqualSlices(f64, &.{ 0, 2.2, 3.8 }, csc_clip_min.values);
    var csc_max_scalar = try csc.maximumScalar(0);
    defer csc_max_scalar.deinit();
    try std.testing.expectEqualSlices(f64, csc_clip_min.values, csc_max_scalar.values);
    var csc_clip_max = try csc.clipMax(3);
    defer csc_clip_max.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1.7, 2.2, 3 }, csc_clip_max.values);
    var csc_min_scalar = try csc.minimumScalar(3);
    defer csc_min_scalar.deinit();
    try std.testing.expectEqualSlices(f64, csc_clip_max.values, csc_min_scalar.values);
    var csc_clip = try csc.clip(-1, 3);
    defer csc_clip.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1, 2.2, 3 }, csc_clip.values);
    try std.testing.expectError(error.InvalidShape, csc.clip(3, -1));
}

test "coo sparse diagnostics and duplicate coordinate access" {
    const gpa = std.testing.allocator;
    var symmetric_dense = try array_mod.Array(f64).fromSlice(gpa, &.{
        4, 1, 0,
        1, 5, 2,
        0, 2, 6,
    }, &.{ 3, 3 });
    defer symmetric_dense.deinit();
    var symmetric = try cooFromDense(f64, symmetric_dense);
    defer symmetric.deinit();

    var diagonal = try symmetric.diagonal();
    defer diagonal.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 4, 5, 6 }, diagonal.data);
    var diagonal_out = try array_mod.Array(f64).zeros(gpa, &.{3});
    defer diagonal_out.deinit();
    try symmetric.diagonalOut(diagonal_out);
    try std.testing.expectEqualSlices(f64, diagonal.data, diagonal_out.data);
    var diagonal_mut = try symmetric.clone();
    defer diagonal_mut.deinit();
    try diagonal_mut.addToDiagonal(1);
    var diagonal_mut_values = try diagonal_mut.diagonal();
    defer diagonal_mut_values.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 5, 6, 7 }, diagonal_mut_values.data);
    try diagonal_mut.setDiagonal(9);
    var diagonal_set_values = try diagonal_mut.diagonal();
    defer diagonal_set_values.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 9, 9, 9 }, diagonal_set_values.data);
    try diagonal_mut.setDiagonalValues(&.{ 1, 2, 3 });
    var diagonal_set_vector_values = try diagonal_mut.diagonal();
    defer diagonal_set_vector_values.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 1, 2, 3 }, diagonal_set_vector_values.data);
    try diagonal_mut.addDiagonalValues(&.{ 1, 1, 1 });
    var diagonal_add_vector_values = try diagonal_mut.diagonal();
    defer diagonal_add_vector_values.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 2, 3, 4 }, diagonal_add_vector_values.data);
    try diagonal_mut.multiplyDiagonalValues(&.{ 2, 3, 4 });
    var diagonal_mul_vector_values = try diagonal_mut.diagonal();
    defer diagonal_mul_vector_values.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 4, 9, 16 }, diagonal_mul_vector_values.data);
    try std.testing.expectError(error.ShapeMismatch, diagonal_mut.setDiagonalVector(&.{1}));
    try std.testing.expectApproxEqAbs(@as(f64, 15), try symmetric.trace(), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 15), try symmetric.traceOffset(0), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 3), try symmetric.traceOffset(1), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 3), try symmetric.traceOffset(-1), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 0), try symmetric.traceOffset(9), 1e-12);
    try std.testing.expect(try symmetric.traceInRange(15, 15));
    try std.testing.expect(try symmetric.traceInRange(14.5, 15.5));
    try std.testing.expect(!(try symmetric.traceInRange(15.5, 16)));
    try std.testing.expectError(error.InvalidShape, symmetric.traceInRange(std.math.nan(f64), 15));
    try std.testing.expectApproxEqAbs(@as(f64, 5), try symmetric.normalizedTrace(), 1e-12);
    try std.testing.expect(try symmetric.normalizedTraceInRange(5, 5));
    try std.testing.expect(try symmetric.normalizedTraceInRange(4.9, 5.1));
    try std.testing.expect(!(try symmetric.normalizedTraceInRange(5.1, 6)));
    try std.testing.expectError(error.InvalidShape, symmetric.normalizedTraceInRange(6, 5));
    try std.testing.expectEqual(@as(usize, 0), try symmetric.missingDiagonalCount());
    try std.testing.expect(try symmetric.missingDiagonalCountMeetsBound(0));
    try std.testing.expect(try symmetric.missingDiagonalCountInRange(0, 0));
    try std.testing.expectEqual(@as(usize, 0), try symmetric.zeroDiagonalCount());
    try std.testing.expect(try symmetric.zeroDiagonalCountMeetsBound(0));
    try std.testing.expect(try symmetric.zeroDiagonalCountInRange(0, 0));
    try std.testing.expectEqual(@as(usize, 1), try symmetric.bandwidth());
    try std.testing.expect(try symmetric.bandwidthMeetsBound(1));
    try std.testing.expect(!(try symmetric.bandwidthMeetsBound(0)));
    try std.testing.expectEqual(@as(usize, 2), try symmetric.columnIntersectionBandwidth());
    try std.testing.expect(try symmetric.columnIntersectionBandwidthMeetsBound(2));
    try std.testing.expect(!(try symmetric.columnIntersectionBandwidthMeetsBound(1)));
    try std.testing.expectEqual(@as(usize, 5), try symmetric.lowerNnz(false));
    try std.testing.expectEqual(@as(usize, 2), try symmetric.lowerNnz(true));
    try std.testing.expectEqual(@as(usize, 5), try symmetric.upperNnz(false));
    try std.testing.expectEqual(@as(usize, 2), try symmetric.upperNnz(true));
    try std.testing.expect(try symmetric.lowerNnzMeetsBound(false, 5));
    try std.testing.expect(!(try symmetric.lowerNnzMeetsBound(false, 4)));
    try std.testing.expect(try symmetric.upperNnzMeetsBound(true, 2));
    try std.testing.expect(!(try symmetric.upperNnzMeetsBound(true, 1)));
    try std.testing.expect(try symmetric.lowerNnzInRange(false, 5, 5));
    try std.testing.expect(try symmetric.upperNnzInRange(true, 0, 2));
    try std.testing.expect(!(try symmetric.lowerNnzInRange(true, 3, 5)));
    try std.testing.expectError(error.InvalidShape, symmetric.upperNnzInRange(false, 6, 5));
    try std.testing.expectEqual(@as(usize, 2), try symmetric.lowerProfile());
    try std.testing.expectEqual(@as(usize, 2), try symmetric.upperProfile());
    const symmetric_profile = try symmetric.profile();
    try std.testing.expectEqual(@as(usize, 2), symmetric_profile.lower);
    try std.testing.expectEqual(@as(usize, 2), symmetric_profile.upper);
    try std.testing.expectEqual(@as(usize, 4), try symmetric_profile.total());
    try std.testing.expect(symmetric_profile.meetsBounds(2, 2));
    try std.testing.expect(try symmetric_profile.totalMeetsBound(4));
    try std.testing.expect(try symmetric.lowerProfileMeetsBound(2));
    try std.testing.expect(!(try symmetric.lowerProfileMeetsBound(1)));
    try std.testing.expect(try symmetric.upperProfileMeetsBound(2));
    try std.testing.expect(!(try symmetric.upperProfileMeetsBound(1)));
    try std.testing.expect(try symmetric.profileMeetsBounds(2, 2));
    try std.testing.expect(!(try symmetric.profileMeetsBounds(1, 2)));
    try std.testing.expect(try symmetric.profileTotalMeetsBound(4));
    try std.testing.expect(!(try symmetric.profileTotalMeetsBound(3)));
    try std.testing.expect(try symmetric.structurallySymmetric());
    try std.testing.expect(try symmetric.numericallySymmetric(1e-12));
    try std.testing.expectApproxEqAbs(@as(f64, 0), try symmetric.symmetryResidualFrobeniusNorm(), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 0), try symmetric.symmetryRelativeResidualFrobeniusNorm(), 1e-12);
    try std.testing.expect(try symmetric.symmetryResidualFrobeniusNormMeetsBound(0));
    try std.testing.expect(try symmetric.symmetryRelativeResidualFrobeniusNormMeetsBound(0));
    try std.testing.expectApproxEqAbs(@as(f64, 2), symmetric.get(1, 2).?, 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 2), try symmetric.getValue(1, 2), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 2), try symmetric.at(1, 2), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 2), try symmetric.getSigned(-2, -1), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 2), try symmetric.atSigned(-2, -1), 1e-12);
    try std.testing.expect(symmetric.get(0, 2) == null);
    try std.testing.expectApproxEqAbs(@as(f64, 0), try symmetric.getValue(0, 2), 1e-12);
    try std.testing.expectError(error.IndexOutOfBounds, symmetric.getValue(0, 3));
    var point_mut = try symmetric.clone();
    defer point_mut.deinit();
    try point_mut.setExisting(1, 2, 7);
    try std.testing.expectApproxEqAbs(@as(f64, 7), point_mut.get(1, 2).?, 1e-12);
    var scalar_coo = try cooFromSlices(f64, gpa, 1, 1, &.{0}, &.{0}, &.{42});
    defer scalar_coo.deinit();
    try std.testing.expectApproxEqAbs(@as(f64, 42), try scalar_coo.item(), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 42), try scalar_coo.itemValue(), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 42), try scalar_coo.scalarValue(), 1e-12);
    try std.testing.expectError(error.ShapeMismatch, point_mut.item());
    try std.testing.expectError(error.InvalidShape, point_mut.setStoredValue(0, 2, 9));
    try std.testing.expectError(error.IndexOutOfBounds, point_mut.setExisting(3, 0, 9));

    var nonsym_dense = try array_mod.Array(f64).fromSlice(gpa, &.{
        1, 2, 0,
        0, 0, 3,
        0, 0, 4,
    }, &.{ 3, 3 });
    defer nonsym_dense.deinit();
    var nonsym = try cooFromDense(f64, nonsym_dense);
    defer nonsym.deinit();
    try std.testing.expectEqual(@as(usize, 1), try nonsym.missingDiagonalCount());
    try std.testing.expect(try nonsym.missingDiagonalCountMeetsBound(1));
    try std.testing.expect(!(try nonsym.missingDiagonalCountMeetsBound(0)));
    try std.testing.expect(try nonsym.missingDiagonalCountInRange(1, 2));
    try std.testing.expect(!(try nonsym.missingDiagonalCountInRange(0, 0)));
    try std.testing.expectError(error.InvalidShape, nonsym.missingDiagonalCountInRange(2, 1));
    try std.testing.expectEqual(@as(usize, 0), try nonsym.zeroDiagonalCount());
    try std.testing.expect(try nonsym.zeroDiagonalCountMeetsBound(0));
    try std.testing.expect(!(try nonsym.zeroDiagonalCountInRange(1, 1)));
    try std.testing.expectEqual(@as(usize, 1), try nonsym.bandwidth());
    try std.testing.expect(!(try nonsym.structurallySymmetric()));
    try std.testing.expect(!(try nonsym.numericallySymmetric(1e-12)));
    try std.testing.expectApproxEqAbs(@sqrt(@as(f64, 26)), try nonsym.symmetryResidualFrobeniusNorm(), 1e-12);
    try std.testing.expectApproxEqAbs(@sqrt(@as(f64, 26)) / @sqrt(@as(f64, 30)), try nonsym.symmetryRelativeResidualFrobeniusNorm(), 1e-12);
    try std.testing.expect(try nonsym.symmetryResidualFrobeniusNormMeetsBound(@sqrt(@as(f64, 26))));
    try std.testing.expect(!(try nonsym.symmetryResidualFrobeniusNormMeetsBound(@sqrt(@as(f64, 26)) - 1e-12)));
    try std.testing.expect(try nonsym.symmetryRelativeResidualFrobeniusNormMeetsBound(@sqrt(@as(f64, 26)) / @sqrt(@as(f64, 30)) + 1e-12));
    try std.testing.expectError(error.InvalidShape, nonsym.symmetryResidualFrobeniusNormMeetsBound(-1));

    var rectangular = try cooFromSlices(f64, gpa, 2, 3, &.{ 0, 1 }, &.{ 0, 2 }, &.{ 1, 2 });
    defer rectangular.deinit();
    try std.testing.expectError(error.NonMatrixArray, rectangular.lowerNnz(false));
    try std.testing.expectError(error.NonMatrixArray, rectangular.upperNnz(false));
    try std.testing.expectError(error.NonMatrixArray, rectangular.missingDiagonalCountMeetsBound(0));
    try std.testing.expectError(error.NonMatrixArray, rectangular.zeroDiagonalCountInRange(0, 1));
    try std.testing.expectError(error.InvalidShape, rectangular.missingDiagonalCountInRange(2, 1));
    try std.testing.expectError(error.NonMatrixArray, rectangular.traceInRange(0, 3));
    try std.testing.expectError(error.NonMatrixArray, rectangular.normalizedTrace());
    try std.testing.expectError(error.NonMatrixArray, rectangular.normalizedTraceInRange(0, 1));
    try std.testing.expectError(error.NonMatrixArray, rectangular.bandwidthMeetsBound(1));
    try std.testing.expectError(error.NonMatrixArray, rectangular.lowerNnzMeetsBound(false, 1));
    try std.testing.expectError(error.NonMatrixArray, rectangular.upperNnzInRange(false, 0, 1));
    try std.testing.expectError(error.NonMatrixArray, rectangular.profile());
    try std.testing.expectError(error.NonMatrixArray, rectangular.symmetryResidualFrobeniusNorm());
    try std.testing.expectError(error.NonMatrixArray, rectangular.symmetryRelativeResidualFrobeniusNorm());
    try std.testing.expectError(error.NonMatrixArray, rectangular.symmetryResidualFrobeniusNormMeetsBound(1));
    try std.testing.expectError(error.NonMatrixArray, rectangular.profileMeetsBounds(1, 1));
    try std.testing.expectError(error.NonMatrixArray, rectangular.profileTotalMeetsBound(1));

    var duplicate_diagonal = try cooFromSlices(f64, gpa, 2, 2, &.{ 0, 0, 1, 1, 1 }, &.{ 0, 0, 0, 1, 1 }, &.{ 1, 2, 3, 4, -4 });
    defer duplicate_diagonal.deinit();
    var duplicate_diag = try duplicate_diagonal.diagonal();
    defer duplicate_diag.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 3, 0 }, duplicate_diag.data);
    var duplicate_diagonal_mut = try duplicate_diagonal.clone();
    defer duplicate_diagonal_mut.deinit();
    try duplicate_diagonal_mut.addToDiagonal(1);
    try std.testing.expectEqualSlices(f64, &.{ 2, 3, 3, 5, -3 }, duplicate_diagonal_mut.values);
    try duplicate_diagonal_mut.setDiagonal(7);
    try std.testing.expectEqualSlices(f64, &.{ 7, 7, 3, 7, 7 }, duplicate_diagonal_mut.values);
    try std.testing.expectApproxEqAbs(@as(f64, 3), try duplicate_diagonal.trace(), 1e-12);
    try std.testing.expect(try duplicate_diagonal.traceInRange(3, 3));
    try std.testing.expectApproxEqAbs(@as(f64, 1.5), try duplicate_diagonal.normalizedTrace(), 1e-12);
    try std.testing.expect(try duplicate_diagonal.normalizedTraceInRange(1.4, 1.6));
    try std.testing.expectEqual(@as(usize, 0), try duplicate_diagonal.missingDiagonalCount());
    try std.testing.expectEqual(@as(usize, 1), try duplicate_diagonal.zeroDiagonalCount());
    try std.testing.expect(try duplicate_diagonal.zeroDiagonalCountMeetsBound(1));
    try std.testing.expect(!(try duplicate_diagonal.zeroDiagonalCountMeetsBound(0)));
    try std.testing.expect(try duplicate_diagonal.zeroDiagonalCountInRange(1, 1));
    try std.testing.expect(!(try duplicate_diagonal.zeroDiagonalCountInRange(0, 0)));
    try std.testing.expectApproxEqAbs(@as(f64, 3), duplicate_diagonal.get(0, 0).?, 1e-12);
    try std.testing.expect(!(try duplicate_diagonal.structurallySymmetric()));

    var empty_square = try cooFromSlices(f64, gpa, 0, 0, &.{}, &.{}, &.{});
    defer empty_square.deinit();
    try std.testing.expectApproxEqAbs(@as(f64, 0), try empty_square.trace(), 1e-12);
    try std.testing.expectError(error.EmptyArray, empty_square.normalizedTrace());
    try std.testing.expectError(error.EmptyArray, empty_square.normalizedTraceInRange(0, 1));

    var duplicate_symmetric = try cooFromSlices(f64, gpa, 2, 2, &.{ 0, 0, 1, 1 }, &.{ 1, 1, 0, 0 }, &.{ 1, 2, 1.5, 1.5 });
    defer duplicate_symmetric.deinit();
    try std.testing.expectEqual(@as(usize, 2), try duplicate_symmetric.missingDiagonalCount());
    try std.testing.expectError(error.InvalidShape, duplicate_symmetric.addToDiagonal(1));
    try std.testing.expect(try duplicate_symmetric.structurallySymmetric());
    try std.testing.expect(try duplicate_symmetric.numericallySymmetric(1e-12));
}

test "sparse complex helpers dense materialize" {
    const gpa = std.testing.allocator;
    const C = array_mod.Complex64;
    const expectComplexHelpers = struct {
        fn check(comptime Matrix: type, matrix: Matrix) !void {
            var real_part = try matrix.real();
            defer real_part.deinit();
            try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, real_part.shape);
            try std.testing.expectEqualSlices(f32, &.{ 1, 2, 2, 4 }, real_part.data);
            var real_out = try array_mod.Array(f32).zeros(matrix.allocator, &.{ 2, 2 });
            defer real_out.deinit();
            try matrix.realOut(real_out);
            try std.testing.expectEqualSlices(f32, real_part.data, real_out.data);

            var imaginary_part = try matrix.imag();
            defer imaginary_part.deinit();
            try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, imaginary_part.shape);
            try std.testing.expectEqualSlices(f32, &.{ 0, 3, -3, 0 }, imaginary_part.data);
            try matrix.imagOut(real_out);
            try std.testing.expectEqualSlices(f32, imaginary_part.data, real_out.data);

            var conjugated = try matrix.conj();
            defer conjugated.deinit();
            try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, conjugated.shape);
            try std.testing.expectEqual(C.init(1, 0), conjugated.data[0]);
            try std.testing.expectEqual(C.init(2, -3), conjugated.data[1]);
            try std.testing.expectEqual(C.init(2, 3), conjugated.data[2]);
            try std.testing.expectEqual(C.init(4, 0), conjugated.data[3]);
            var complex_out = try array_mod.Array(C).zeros(matrix.allocator, &.{ 2, 2 });
            defer complex_out.deinit();
            try matrix.conjOut(complex_out);
            try std.testing.expectEqualSlices(C, conjugated.data, complex_out.data);

            var conjugated_alias = try matrix.conjugate();
            defer conjugated_alias.deinit();
            try std.testing.expectEqualSlices(C, conjugated.data, conjugated_alias.data);
            try matrix.conjugateOut(complex_out);
            try std.testing.expectEqualSlices(C, conjugated_alias.data, complex_out.data);

            try std.testing.expect(try matrix.isHermitian(C.init(1e-5, 0), C.init(1e-5, 0)));

            var magnitudes = try matrix.magnitude();
            defer magnitudes.deinit();
            try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, magnitudes.shape);
            try std.testing.expectApproxEqAbs(@as(f32, 1), magnitudes.data[0], 1e-6);
            try std.testing.expectApproxEqAbs(@as(f32, @sqrt(13.0)), magnitudes.data[1], 1e-6);
            try std.testing.expectApproxEqAbs(@as(f32, @sqrt(13.0)), magnitudes.data[2], 1e-6);
            try std.testing.expectApproxEqAbs(@as(f32, 4), magnitudes.data[3], 1e-6);
            try matrix.magnitudeOut(real_out);
            try std.testing.expectEqualSlices(f32, magnitudes.data, real_out.data);

            var abs_alias = try matrix.absComplex();
            defer abs_alias.deinit();
            try std.testing.expectEqualSlices(f32, magnitudes.data, abs_alias.data);
            try matrix.absComplexOut(real_out);
            try std.testing.expectEqualSlices(f32, abs_alias.data, real_out.data);

            var angles = try matrix.angle();
            defer angles.deinit();
            try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, angles.shape);
            try std.testing.expectApproxEqAbs(@as(f32, 0), angles.data[0], 1e-6);
            try std.testing.expectApproxEqAbs(@as(f32, std.math.atan2(@as(f32, 3), @as(f32, 2))), angles.data[1], 1e-6);
            try std.testing.expectApproxEqAbs(@as(f32, std.math.atan2(@as(f32, -3), @as(f32, 2))), angles.data[2], 1e-6);
            try std.testing.expectApproxEqAbs(@as(f32, 0), angles.data[3], 1e-6);
            try matrix.angleOut(real_out);
            try std.testing.expectEqualSlices(f32, angles.data, real_out.data);

            var phases = try matrix.phase();
            defer phases.deinit();
            try std.testing.expectEqualSlices(f32, angles.data, phases.data);
            try matrix.phaseOut(real_out);
            try std.testing.expectEqualSlices(f32, phases.data, real_out.data);

            var real_mask = try matrix.isreal();
            defer real_mask.deinit();
            try std.testing.expectEqualSlices(bool, &.{ true, false, false, true }, real_mask.data);
            var bool_out = try array_mod.Array(bool).zeros(matrix.allocator, &.{ 2, 2 });
            defer bool_out.deinit();
            try matrix.isrealOut(bool_out);
            try std.testing.expectEqualSlices(bool, real_mask.data, bool_out.data);

            var real_mask_alias = try matrix.isReal();
            defer real_mask_alias.deinit();
            try std.testing.expectEqualSlices(bool, real_mask.data, real_mask_alias.data);
            try matrix.isRealOut(bool_out);
            try std.testing.expectEqualSlices(bool, real_mask_alias.data, bool_out.data);

            var complex_mask = try matrix.iscomplex();
            defer complex_mask.deinit();
            try std.testing.expectEqualSlices(bool, &.{ false, true, true, false }, complex_mask.data);
            try matrix.iscomplexOut(bool_out);
            try std.testing.expectEqualSlices(bool, complex_mask.data, bool_out.data);
        }
    }.check;

    var coo = try cooFromSlices(C, gpa, 2, 2, &.{ 0, 0, 1, 1 }, &.{ 0, 1, 0, 1 }, &.{
        C.init(1, 0),
        C.init(2, 3),
        C.init(2, -3),
        C.init(4, 0),
    });
    defer coo.deinit();
    try expectComplexHelpers(@TypeOf(coo), coo);

    var csr = try coo.toCsr();
    defer csr.deinit();
    try expectComplexHelpers(@TypeOf(csr), csr);

    var csc = try coo.toCsc();
    defer csc.deinit();
    try expectComplexHelpers(@TypeOf(csc), csc);
}

test "csr sparse bridge dense roundtrip and matvec" {
    const gpa = std.testing.allocator;
    var dense = try array_mod.Array(f64).fromSlice(gpa, &.{
        10, 0, 2, 0,
        0,  3, 0, 4,
        5,  0, 0, 6,
    }, &.{ 3, 4 });
    defer dense.deinit();

    var csr = try csrFromDense(f64, dense);
    defer csr.deinit();
    var csr_from_array = try @TypeOf(csr).fromArray(dense);
    defer csr_from_array.deinit();
    try std.testing.expectEqualSlices(usize, csr.row_offsets, csr_from_array.row_offsets);
    try std.testing.expectEqualSlices(usize, csr.col_indices, csr_from_array.col_indices);
    try std.testing.expectEqualSlices(f64, csr.values, csr_from_array.values);
    try std.testing.expectEqual(@as(usize, 6), csr.nnz());
    try std.testing.expectEqualSlices(usize, &.{ 0, 2, 4, 6 }, csr.row_offsets);
    try std.testing.expectEqualSlices(usize, &.{ 0, 2, 1, 3, 0, 3 }, csr.col_indices);
    try std.testing.expectEqualSlices(f64, &.{ 10, 2, 3, 4, 5, 6 }, csr.values);
    var csr_scalar_out = try array_mod.Array(bool).zeros(gpa, &.{ 3, 4 });
    defer csr_scalar_out.deinit();
    try csr.gtScalarOut(4, csr_scalar_out);
    try std.testing.expectEqualSlices(bool, &.{ true, false, false, false, false, false, false, false, true, false, false, true }, csr_scalar_out.data);
    var csr_point_mut = try csr.clone();
    defer csr_point_mut.deinit();
    try csr_point_mut.setExisting(0, 2, 11);
    try std.testing.expectApproxEqAbs(@as(f64, 11), csr_point_mut.get(0, 2).?, 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 11), try csr_point_mut.getValue(0, 2), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 11), try csr_point_mut.at(0, 2), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 11), try csr_point_mut.getSigned(0, -2), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 0), try csr_point_mut.getValue(0, 1), 1e-12);
    try std.testing.expectError(error.IndexOutOfBounds, csr_point_mut.at(3, 0));
    try std.testing.expectError(error.InvalidShape, csr_point_mut.setStoredValue(0, 1, 9));
    try std.testing.expectError(error.IndexOutOfBounds, csr_point_mut.setExisting(3, 0, 9));
    var square_dense = try array_mod.Array(f64).fromSlice(gpa, &.{
        4, 1, 0,
        1, 5, 2,
        0, 2, 6,
    }, &.{ 3, 3 });
    defer square_dense.deinit();
    var square_csr = try csrFromDense(f64, square_dense);
    defer square_csr.deinit();
    try square_csr.addToDiagonal(2);
    var square_csr_diag = try square_csr.diagonal();
    defer square_csr_diag.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 6, 7, 8 }, square_csr_diag.data);
    var square_diag_out = try array_mod.Array(f64).zeros(gpa, &.{3});
    defer square_diag_out.deinit();
    try square_csr.diagonalOut(square_diag_out);
    try std.testing.expectEqualSlices(f64, square_csr_diag.data, square_diag_out.data);
    try square_csr.setDiagonal(3);
    var square_csr_set_diag = try square_csr.diagonal();
    defer square_csr_set_diag.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 3, 3, 3 }, square_csr_set_diag.data);
    try square_csr.setDiagonalVector(&.{ 1, 2, 3 });
    try square_csr.addDiagonalVector(&.{ 1, 1, 1 });
    try square_csr.multiplyDiagonalVector(&.{ 2, 3, 4 });
    var square_csr_vector_diag = try square_csr.diagonal();
    defer square_csr_vector_diag.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 4, 9, 16 }, square_csr_vector_diag.data);
    try std.testing.expectApproxEqAbs(@as(f64, 3), try square_csr.traceOffset(1), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 3), try square_csr.traceOffset(-1), 1e-12);
    try std.testing.expectError(error.ShapeMismatch, square_csr.addDiagonalValues(&.{1}));
    var missing_csr = try csrFromCompressed(f64, gpa, 2, 2, &.{ 0, 1, 2 }, &.{ 1, 0 }, &.{ 1, 1 });
    defer missing_csr.deinit();
    try std.testing.expectError(error.InvalidShape, missing_csr.setDiagonal(1));

    var dense2 = try csr.toDense();
    defer dense2.deinit();
    try std.testing.expectEqualSlices(f64, dense.data, dense2.data);
    var array2 = try csr.toArray();
    defer array2.deinit();
    try std.testing.expectEqualSlices(f64, dense.data, array2.data);
    var csr_copy_slice: [12]f64 = undefined;
    try csr.copyToSlice(&csr_copy_slice);
    try std.testing.expectEqualSlices(f64, dense.data, &csr_copy_slice);
    const csr_owned_slice = try csr.toOwnedSlice(gpa);
    defer gpa.free(csr_owned_slice);
    try std.testing.expectEqualSlices(f64, dense.data, csr_owned_slice);
    var csr_materialized = try csr.materializeAndSynchronize();
    defer csr_materialized.deinit();
    try std.testing.expectEqualSlices(f64, dense.data, csr_materialized.data);
    try std.testing.expect(!csr.hasPendingWork());
    try csr.synchronize();

    var csc = try csr.toCsc();
    defer csc.deinit();
    var csc_from_array = try @TypeOf(csc).fromArray(dense);
    defer csc_from_array.deinit();
    try std.testing.expectEqualSlices(usize, csc.col_offsets, csc_from_array.col_offsets);
    try std.testing.expectEqualSlices(usize, csc.row_indices, csc_from_array.row_indices);
    try std.testing.expectEqualSlices(f64, csc.values, csc_from_array.values);
    try std.testing.expectEqualSlices(usize, &.{ 0, 2, 3, 4, 6 }, csc.col_offsets);
    try std.testing.expectEqualSlices(usize, &.{ 0, 2, 1, 0, 1, 2 }, csc.row_indices);
    try std.testing.expectEqualSlices(f64, &.{ 10, 5, 3, 2, 4, 6 }, csc.values);
    var csc_scalar_out = try array_mod.Array(bool).zeros(gpa, &.{ 3, 4 });
    defer csc_scalar_out.deinit();
    try csc.gtScalarOut(4, csc_scalar_out);
    try std.testing.expectEqualSlices(bool, &.{ true, false, false, false, false, false, false, false, true, false, false, true }, csc_scalar_out.data);
    var csc_point_mut = try csc.clone();
    defer csc_point_mut.deinit();
    try csc_point_mut.setExisting(2, 0, 12);
    try std.testing.expectApproxEqAbs(@as(f64, 12), csc_point_mut.get(2, 0).?, 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 12), try csc_point_mut.getValue(2, 0), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 12), try csc_point_mut.at(2, 0), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 12), try csc_point_mut.atSigned(-1, 0), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 0), try csc_point_mut.getValue(0, 1), 1e-12);
    try std.testing.expectError(error.IndexOutOfBounds, csc_point_mut.getSigned(0, 4));
    try std.testing.expectError(error.InvalidShape, csc_point_mut.setStoredValue(0, 1, 9));
    try std.testing.expectError(error.IndexOutOfBounds, csc_point_mut.setExisting(0, 4, 9));
    var square_csc = try cscFromDense(f64, square_dense);
    defer square_csc.deinit();
    try square_csc.addToDiagonal(2);
    var square_csc_diag = try square_csc.diagonal();
    defer square_csc_diag.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 6, 7, 8 }, square_csc_diag.data);
    try square_csc.diagonalOut(square_diag_out);
    try std.testing.expectEqualSlices(f64, square_csc_diag.data, square_diag_out.data);
    try square_csc.setDiagonal(3);
    var square_csc_set_diag = try square_csc.diagonal();
    defer square_csc_set_diag.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 3, 3, 3 }, square_csc_set_diag.data);
    try square_csc.setDiagonalVector(&.{ 1, 2, 3 });
    try square_csc.addDiagonalVector(&.{ 1, 1, 1 });
    try square_csc.multiplyDiagonalVector(&.{ 2, 3, 4 });
    var square_csc_vector_diag = try square_csc.diagonal();
    defer square_csc_vector_diag.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 4, 9, 16 }, square_csc_vector_diag.data);
    try std.testing.expectApproxEqAbs(@as(f64, 3), try square_csc.traceOffset(1), 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 3), try square_csc.traceOffset(-1), 1e-12);
    try std.testing.expectError(error.ShapeMismatch, square_csc.multiplyDiagonalValues(&.{1}));
    var missing_csc = try cscFromCompressed(f64, gpa, 2, 2, &.{ 0, 1, 2 }, &.{ 1, 0 }, &.{ 1, 1 });
    defer missing_csc.deinit();
    try std.testing.expectError(error.InvalidShape, missing_csc.addToDiagonal(1));
    var csc_dense = try csc.toDense();
    defer csc_dense.deinit();
    try std.testing.expectEqualSlices(f64, dense.data, csc_dense.data);
    var csc_array = try csc.toArray();
    defer csc_array.deinit();
    try std.testing.expectEqualSlices(f64, dense.data, csc_array.data);
    var csc_copy_slice: [12]f64 = undefined;
    try csc.copyToSlice(&csc_copy_slice);
    try std.testing.expectEqualSlices(f64, dense.data, &csc_copy_slice);
    const csc_owned_slice = try csc.toOwnedSlice(gpa);
    defer gpa.free(csc_owned_slice);
    try std.testing.expectEqualSlices(f64, dense.data, csc_owned_slice);
    var csc_materialized = try csc.materialize();
    defer csc_materialized.deinit();
    try std.testing.expectEqualSlices(f64, dense.data, csc_materialized.data);
    try std.testing.expect(!csc.hasPendingWork());
    try csc.synchronize();

    var x = try array_mod.Array(f64).fromSlice(gpa, &.{ 1, 2, 3, 4 }, &.{4});
    defer x.deinit();
    var y = try csr.matvec(x);
    defer y.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 16, 22, 29 }, y.data);
}

test "csr sparse matmat transpose and statistics" {
    const gpa = std.testing.allocator;
    var dense = try array_mod.Array(f64).fromSlice(gpa, &.{
        1, 0, 2,
        0, 3, 0,
    }, &.{ 2, 3 });
    defer dense.deinit();
    var csr = try csrFromDense(f64, dense);
    defer csr.deinit();

    var rhs = try array_mod.Array(f64).fromSlice(gpa, &.{
        1, 2,
        3, 4,
        5, 6,
    }, &.{ 3, 2 });
    defer rhs.deinit();
    var product = try csr.matmat(rhs);
    defer product.deinit();
    try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, product.shape);
    try std.testing.expectEqualSlices(f64, &.{ 11, 14, 9, 12 }, product.data);

    var sparse_rhs_dense = try array_mod.Array(f64).fromSlice(gpa, &.{
        8, 4,
        5, 0,
        6, 7,
    }, &.{ 3, 2 });
    defer sparse_rhs_dense.deinit();
    var sparse_rhs = try csrFromDense(f64, sparse_rhs_dense);
    defer sparse_rhs.deinit();
    var sparse_product = try csr.matmulSparse(sparse_rhs);
    defer sparse_product.deinit();
    try std.testing.expectEqual(@as(usize, 3), sparse_product.nnz());
    try std.testing.expectEqualSlices(usize, &.{ 0, 2, 3 }, sparse_product.row_offsets);
    try std.testing.expectEqualSlices(usize, &.{ 0, 1, 0 }, sparse_product.col_indices);
    try std.testing.expectEqualSlices(f64, &.{ 20, 18, 15 }, sparse_product.values);
    var sparse_product_dense = try sparse_product.toDense();
    defer sparse_product_dense.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 20, 18, 15, 0 }, sparse_product_dense.data);

    var coo_lhs = try csr.toCoo();
    defer coo_lhs.deinit();
    var coo_rhs = try sparse_rhs.toCoo();
    defer coo_rhs.deinit();
    var coo_product = try coo_lhs.matmulSparse(coo_rhs);
    defer coo_product.deinit();
    try std.testing.expectEqualSlices(usize, &.{ 0, 0, 1 }, coo_product.row_indices);
    try std.testing.expectEqualSlices(usize, &.{ 0, 1, 0 }, coo_product.col_indices);
    try std.testing.expectEqualSlices(f64, &.{ 20, 18, 15 }, coo_product.values);

    var csc_lhs = try csr.toCsc();
    defer csc_lhs.deinit();
    var csc_rhs = try sparse_rhs.toCsc();
    defer csc_rhs.deinit();
    var csc_product = try csc_lhs.matmulSparse(csc_rhs);
    defer csc_product.deinit();
    try std.testing.expectEqualSlices(usize, &.{ 0, 2, 3 }, csc_product.col_offsets);
    try std.testing.expectEqualSlices(usize, &.{ 0, 1, 0 }, csc_product.row_indices);
    try std.testing.expectEqualSlices(f64, &.{ 20, 15, 18 }, csc_product.values);
    try std.testing.expectError(error.ShapeMismatch, sparse_rhs.matmulSparse(sparse_rhs));

    var transposed = try csr.transpose();
    defer transposed.deinit();
    try std.testing.expectEqual(@as(usize, 3), transposed.rows);
    try std.testing.expectEqual(@as(usize, 2), transposed.cols);
    var transposed_dense = try transposed.toDense();
    defer transposed_dense.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 1, 0, 0, 3, 2, 0 }, transposed_dense.data);
    var csr_mt = try csr.matrixTranspose();
    defer csr_mt.deinit();
    var csr_mt_dense = try csr_mt.toDense();
    defer csr_mt_dense.deinit();
    try std.testing.expectEqualSlices(f64, transposed_dense.data, csr_mt_dense.data);
    var csr_m_t = try csr.mT();
    defer csr_m_t.deinit();
    var csr_m_t_dense = try csr_m_t.toDense();
    defer csr_m_t_dense.deinit();
    try std.testing.expectEqualSlices(f64, transposed_dense.data, csr_m_t_dense.data);

    var csc_transposed = try csc_lhs.transpose();
    defer csc_transposed.deinit();
    var csc_transposed_dense = try csc_transposed.toDense();
    defer csc_transposed_dense.deinit();
    try std.testing.expectEqualSlices(f64, transposed_dense.data, csc_transposed_dense.data);
    var csc_mt = try csc_lhs.matrixTranspose();
    defer csc_mt.deinit();
    var csc_mt_dense = try csc_mt.toDense();
    defer csc_mt_dense.deinit();
    try std.testing.expectEqualSlices(f64, transposed_dense.data, csc_mt_dense.data);
    var csc_m_t = try csc_lhs.mT();
    defer csc_m_t.deinit();
    var csc_m_t_dense = try csc_m_t.toDense();
    defer csc_m_t_dense.deinit();
    try std.testing.expectEqualSlices(f64, transposed_dense.data, csc_m_t_dense.data);

    try std.testing.expectApproxEqAbs(@as(f64, 6), csr.sum(), 1e-12);
    try std.testing.expect(try csr.sumInRange(6, 6));
    try std.testing.expect(try csr.sumInRange(5.5, 6.5));
    try std.testing.expect(!(try csr.sumInRange(6.5, 7)));
    try std.testing.expectError(error.InvalidShape, csr.sumInRange(7, 6));
    try std.testing.expectApproxEqAbs(@as(f64, 6), csr.absSum(), 1e-12);
    try std.testing.expect(try csr.absSumInRange(6, 6));
    try std.testing.expect(try csr.absSumInRange(5, 7));
    try std.testing.expect(!(try csr.absSumInRange(7, 8)));
    try std.testing.expectError(error.InvalidShape, csr.absSumInRange(std.math.nan(f64), 6));
    try std.testing.expectApproxEqAbs(@as(f64, @sqrt(14.0)), csr.frobeniusNorm(), 1e-12);
    try std.testing.expect(try csr.frobeniusNormMeetsBound(@sqrt(@as(f64, 14.0))));
    try std.testing.expect(!(try csr.frobeniusNormMeetsBound(@sqrt(@as(f64, 14.0)) - 1e-12)));
    try std.testing.expectError(error.InvalidShape, csr.frobeniusNormMeetsBound(std.math.nan(f64)));
    try std.testing.expectApproxEqAbs(@as(f64, 3), try csr.oneNorm(), 1e-12);
    try std.testing.expect(try csr.oneNormMeetsBound(3));
    try std.testing.expect(!(try csr.oneNormMeetsBound(2.999)));
    try std.testing.expectError(error.InvalidShape, csr.oneNormMeetsBound(-1));
    try std.testing.expectApproxEqAbs(@as(f64, 3), try csr.infNorm(), 1e-12);
    try std.testing.expect(try csr.infNormMeetsBound(3));
    try std.testing.expect(!(try csr.infNormMeetsBound(2.999)));
    try std.testing.expectError(error.InvalidShape, csr.infNormMeetsBound(std.math.inf(f64)));
    try std.testing.expectApproxEqAbs(@as(f64, 0.5), try csr.density(), 1e-12);
}

test "csr sparse row and column statistics" {
    const gpa = std.testing.allocator;
    var dense = try array_mod.Array(f64).fromSlice(gpa, &.{
        1, 0, -2,
        0, 3, 0,
        4, 0, 5,
    }, &.{ 3, 3 });
    defer dense.deinit();
    var csr = try csrFromDense(f64, dense);
    defer csr.deinit();

    try std.testing.expectApproxEqAbs(@as(f64, -2), try csr.minValue(), 1e-12);
    try std.testing.expectEqual(@as(usize, 1), try csr.minValueIndex());
    try std.testing.expectApproxEqAbs(@as(f64, 5), try csr.maxValue(), 1e-12);
    try std.testing.expectEqual(@as(usize, 4), try csr.maxValueIndex());
    try std.testing.expectApproxEqAbs(@as(f64, 1), try csr.minAbsValue(), 1e-12);
    try std.testing.expectEqual(@as(usize, 0), try csr.minAbsValueIndex());
    try std.testing.expectApproxEqAbs(@as(f64, 5), try csr.maxAbsValue(), 1e-12);
    try std.testing.expectEqual(@as(usize, 4), try csr.maxAbsValueIndex());
    const expected_mean = @as(f64, 11.0 / 9.0);
    const expected_variance = @as(f64, 55.0 / 9.0) - expected_mean * expected_mean;
    const expected_stddev = @sqrt(expected_variance);
    const expected_sample_variance = @as(f64, (55.0 - (11.0 * 11.0) / 9.0) / 8.0);
    const expected_sample_stddev = @sqrt(expected_sample_variance);
    try std.testing.expectApproxEqAbs(expected_mean, try csr.mean(), 1e-12);
    try std.testing.expect(try csr.meanInRange(expected_mean, expected_mean));
    try std.testing.expect(try csr.meanInRange(1.2, 1.3));
    try std.testing.expect(!(try csr.meanInRange(1.3, 1.4)));
    try std.testing.expectError(error.InvalidShape, csr.meanInRange(std.math.nan(f64), expected_mean));
    try std.testing.expectApproxEqAbs(expected_variance, try csr.variance(0), 1e-12);
    try std.testing.expect(try csr.varianceInRange(0, expected_variance - 1e-12, expected_variance + 1e-12));
    try std.testing.expect(try csr.varianceInRange(0, 4.6, 4.7));
    try std.testing.expect(!(try csr.varianceInRange(0, 4.7, 4.8)));
    try std.testing.expectError(error.InvalidShape, csr.varianceInRange(0, -0.1, 1));
    try std.testing.expectApproxEqAbs(expected_stddev, try csr.stddev(0), 1e-12);
    try std.testing.expect(try csr.stddevInRange(0, expected_stddev - 1e-12, expected_stddev + 1e-12));
    try std.testing.expect(!(try csr.stddevInRange(0, expected_stddev + 0.1, expected_stddev + 0.2)));
    try std.testing.expectError(error.InvalidShape, csr.stddevInRange(0, 2, 1));
    try std.testing.expectApproxEqAbs(expected_sample_variance, try csr.sampleVariance(), 1e-12);
    try std.testing.expect(try csr.sampleVarianceInRange(expected_sample_variance - 1e-12, expected_sample_variance + 1e-12));
    try std.testing.expect(!(try csr.sampleVarianceInRange(expected_sample_variance + 0.1, expected_sample_variance + 0.2)));
    try std.testing.expectApproxEqAbs(expected_sample_stddev, try csr.sampleStddev(), 1e-12);
    try std.testing.expect(try csr.sampleStddevInRange(expected_sample_stddev - 1e-12, expected_sample_stddev + 1e-12));
    try std.testing.expectError(error.InvalidShape, csr.sampleStddevInRange(-0.1, expected_sample_stddev));

    var row_vars = try csr.rowVariances(0);
    defer row_vars.deinit();
    try std.testing.expectApproxEqAbs(@as(f64, 14.0 / 9.0), row_vars.data[0], 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 2), row_vars.data[1], 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 14.0 / 3.0), row_vars.data[2], 1e-12);
    try std.testing.expect(try csr.rowVariancesInRange(0, 14.0 / 9.0, 14.0 / 3.0));
    try std.testing.expect(!(try csr.rowVariancesInRange(0, 2.1, 14.0 / 3.0)));
    try std.testing.expectError(error.InvalidShape, csr.rowVariancesInRange(0, -0.1, 1));
    var col_vars = try csr.columnVariances(0);
    defer col_vars.deinit();
    try std.testing.expectApproxEqAbs(@as(f64, 26.0 / 9.0), col_vars.data[0], 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 2), col_vars.data[1], 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 26.0 / 3.0), col_vars.data[2], 1e-12);
    try std.testing.expect(try csr.columnVariancesInRange(0, 2, 26.0 / 3.0));
    try std.testing.expect(!(try csr.columnVariancesInRange(0, 2.1, 26.0 / 3.0)));
    try std.testing.expect(try csr.columnSampleVariancesInRange(3, 13));
    try std.testing.expect(!(try csr.columnSampleVariancesInRange(4, 13)));
    try std.testing.expect(try csr.columnSampleStddevsInRange(@sqrt(3.0), @sqrt(13.0)));
    try std.testing.expect(!(try csr.columnSampleStddevsInRange(1.8, @sqrt(13.0))));
    var row_stds = try csr.rowStddevs(0);
    defer row_stds.deinit();
    try std.testing.expectApproxEqAbs(@sqrt(14.0 / 9.0), row_stds.data[0], 1e-12);
    try std.testing.expect(try csr.rowStddevsInRange(0, @sqrt(14.0 / 9.0), @sqrt(14.0 / 3.0)));
    try std.testing.expect(!(try csr.rowStddevsInRange(0, 1.5, 2)));
    try std.testing.expectError(error.InvalidShape, csr.rowStddevsInRange(0, -0.1, 1));
    var col_stds = try csr.columnStddevs(0);
    defer col_stds.deinit();
    try std.testing.expectApproxEqAbs(@sqrt(26.0 / 9.0), col_stds.data[0], 1e-12);
    try std.testing.expect(try csr.columnStddevsInRange(0, @sqrt(2.0), @sqrt(26.0 / 3.0)));
    try std.testing.expect(!(try csr.columnStddevsInRange(0, 1.5, @sqrt(26.0 / 3.0))));
    var row_sample_vars = try csr.rowSampleVariances();
    defer row_sample_vars.deinit();
    try std.testing.expectApproxEqAbs(@as(f64, 7.0 / 3.0), row_sample_vars.data[0], 1e-12);
    try std.testing.expect(try csr.rowSampleVariancesInRange(7.0 / 3.0, 7));
    try std.testing.expect(!(try csr.rowSampleVariancesInRange(2.5, 7)));
    try std.testing.expect(try csr.rowSampleStddevsInRange(@sqrt(7.0 / 3.0), @sqrt(7.0)));
    try std.testing.expect(!(try csr.rowSampleStddevsInRange(1.6, @sqrt(7.0))));

    var row_means = try csr.rowMeans();
    defer row_means.deinit();
    try std.testing.expectApproxEqAbs(@as(f64, -1.0 / 3.0), row_means.data[0], 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 1), row_means.data[1], 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 3), row_means.data[2], 1e-12);
    try std.testing.expect(try csr.rowMeansInRange(-1.0 / 3.0, 3));
    try std.testing.expect(!(try csr.rowMeansInRange(0, 3)));
    try std.testing.expectError(error.InvalidShape, csr.rowMeansInRange(3, 2));
    var col_means = try csr.columnMeans();
    defer col_means.deinit();
    try std.testing.expectApproxEqAbs(@as(f64, 5.0 / 3.0), col_means.data[0], 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 1), col_means.data[1], 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 1), col_means.data[2], 1e-12);
    try std.testing.expect(try csr.columnMeansInRange(1, 5.0 / 3.0));
    try std.testing.expect(!(try csr.columnMeansInRange(1.1, 5.0 / 3.0)));

    var row_mins = try csr.rowMins();
    defer row_mins.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -2, 0, 0 }, row_mins.data);
    try std.testing.expect(try csr.rowMinsInRange(-2, 0));
    try std.testing.expect(!(try csr.rowMinsInRange(-1, 0)));
    try std.testing.expectError(error.InvalidShape, csr.rowMinsInRange(1, 0));
    var row_maxes = try csr.rowMaxes();
    defer row_maxes.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 1, 3, 5 }, row_maxes.data);
    try std.testing.expect(try csr.rowMaxesInRange(1, 5));
    try std.testing.expect(!(try csr.rowMaxesInRange(2, 5)));
    var col_mins = try csr.columnMins();
    defer col_mins.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 0, 0, -2 }, col_mins.data);
    try std.testing.expect(try csr.columnMinsInRange(-2, 0));
    try std.testing.expect(!(try csr.columnMinsInRange(-1, 0)));
    var col_maxes = try csr.columnMaxes();
    defer col_maxes.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 4, 3, 5 }, col_maxes.data);
    try std.testing.expect(try csr.columnMaxesInRange(3, 5));
    try std.testing.expect(!(try csr.columnMaxesInRange(4, 5)));
    var row_min_abs = try csr.rowMinAbs();
    defer row_min_abs.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 1, 3, 4 }, row_min_abs.data);
    try std.testing.expect(try csr.rowMinAbsInRange(1, 4));
    try std.testing.expect(!(try csr.rowMinAbsInRange(2, 4)));
    try std.testing.expectError(error.InvalidShape, csr.rowMinAbsInRange(5, 4));
    var row_max_abs = try csr.rowMaxAbs();
    defer row_max_abs.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 2, 3, 5 }, row_max_abs.data);
    try std.testing.expect(try csr.rowMaxAbsInRange(2, 5));
    try std.testing.expect(!(try csr.rowMaxAbsInRange(3, 5)));
    var col_min_abs = try csr.columnMinAbs();
    defer col_min_abs.deinit();
